import "./style.css";

declare global {
  interface Window { go?: { app?: { App?: Record<string, (...args: unknown[]) => Promise<any>> } }; runtime?: { EventsOn?: (eventName:string, callback:(...data:any[])=>void)=>()=>void } }
  interface SVGPathElement { hidden: boolean }
}

type AnyRecord = Record<string, any>;
type Draft = { data: AnyRecord; dirty: boolean };

const root = document.querySelector<HTMLDivElement>("#app")!;
let state: AnyRecord = {};
let tabs: string[] = [];
let activeId = "";
let requestTab = "params";
let responseTab = "pretty";
let sidebarMode = "collections";
let sendingId = "";
let loadRunningId = "";
let activeFlowId = "";
let selectedFlowNodeId = "";
let flowRunningId = "";
let updateCheckInProgress = false;
const drafts = new Map<string, Draft>();
const responses = new Map<string, AnyRecord>();
const collapsedTree = new Set<string>();
const loadConfigs = new Map<string,{concurrency:number;totalRequests:number;delayMs:number}>();
const loadResults = new Map<string,AnyRecord>();
const selectedLoadRuns = new Map<string,string>();
const comparedLoadRuns = new Map<string,string>();
const loadViewModes = new Map<string,"table"|"chart">();
const dirtyFlows = new Set<string>();
class FlowResultMap extends Map<string,AnyRecord>{override get(key:string):AnyRecord{return super.get(key)!}}
const flowResults = new FlowResultMap();
const flowLiveNodes = new Map<string,{status:string;iteration:number}>();
const flowLiveEdges = new Map<string,{status:string;iteration:number}>();
let flowNodeDrag: {nodeId:string;startX:number;startY:number;originX:number;originY:number}|null = null;
let flowConnectionDrag: {sourceId:string;sourceHandle:string}|null = null;
let flowPendingAdd: {sourceId:string;sourceHandle:string}|null = null;

const api = async (method: string, ...args: unknown[]) => {
  const fn = window.go?.app?.App?.[method];
  if (!fn) throw new Error(`Backend method ${method} is unavailable. Run the app through Wails.`);
  return fn(...args);
};

const esc = (value: unknown) => String(value ?? "").replace(/[&<>'"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]!));
const uid = () => crypto.randomUUID();
const activeWorkspace = () => state.settings?.activeWorkspaceId || state.workspaces?.[0]?.id || "";
const activeRequest = () => drafts.get(activeId)?.data;
const requestsForWorkspace = () => (state.requests || []).filter((r: AnyRecord) => r.workspaceId === activeWorkspace());
const collectionsForWorkspace = () => (state.collections || []).filter((c: AnyRecord) => c.workspaceId === activeWorkspace());
const environmentsForWorkspace = () => (state.environments || []).filter((e: AnyRecord) => e.workspaceId === activeWorkspace());
const flowsForWorkspace = () => (state.flows || []).filter((flow: AnyRecord) => flow.workspaceId === activeWorkspace());
const activeFlow = () => (state.flows || []).find((flow: AnyRecord) => flow.id === activeFlowId);
const methodClass = (request: AnyRecord) => request.protocol === "SOAP" ? "SOAP" : (request.method || "GET").toUpperCase();
const markDirty = () => { const draft = drafts.get(activeId); if (draft) { draft.dirty = true; renderTabs(); } };

function toast(message: string, error = false) {
  let stack = document.querySelector<HTMLDivElement>(".toast-stack");
  if (!stack) { stack = document.createElement("div"); stack.className = "toast-stack"; document.body.append(stack); }
  const item = document.createElement("div"); item.className = `toast ${error ? "error" : ""}`; item.textContent = message; stack.append(item);
  setTimeout(() => item.remove(), 4200);
}

async function bootstrap() {
  try {
    state = await api("Bootstrap");
    state.flows ||= [];
    for(const id of state.settings?.collapsedTreeIds||[])collapsedTree.add(id);
    tabs = (state.openTabs || []).filter((id: string) => state.requests.some((r: AnyRecord) => r.id === id));
    for (const request of state.requests) drafts.set(request.id, { data: structuredClone(request), dirty: false });
    activeId = tabs[0] || "";
    window.runtime?.EventsOn?.("flow:progress",(payload:AnyRecord)=>{if(!payload||payload.flowId!==activeFlowId)return;if(payload.nodeId)flowLiveNodes.set(payload.nodeId,{status:payload.status||"",iteration:Number(payload.iteration)||0});if(payload.edgeId)flowLiveEdges.set(payload.edgeId,{status:payload.status||"",iteration:Number(payload.iteration)||0});renderWorkspace()});
    applyTheme(); renderShell();
    void checkForUpdates(false);
  } catch (error) {
    root.innerHTML = `<div class="boot"><div><div class="forge-mark" style="margin:auto">!</div><h2>Metriyon API could not start</h2><p class="muted">${esc(error)}</p></div></div>`;
  }
}

function applyTheme() {
  const theme = state.settings?.theme || "dark";
  const light = theme === "light" || (theme === "system" && matchMedia("(prefers-color-scheme: light)").matches);
  document.documentElement.classList.toggle("light", light);
  document.documentElement.style.setProperty("--sidebar", `${state.settings?.sidebarWidth || 288}px`);
  document.documentElement.style.setProperty("--split", `${state.settings?.editorSplitPercent || 52}%`);
}

function renderShell() {
  root.innerHTML = `<div class="shell">
    <header class="topbar">
      <div class="brand"><div class="forge-mark">M</div><span>Metriyon API</span><span class="badge">v${esc(state.version)}</span></div>
      <select class="select" id="workspace-select" title="Active workspace">${(state.workspaces||[]).map((w:AnyRecord)=>`<option value="${w.id}" ${w.id===activeWorkspace()?"selected":""}>${esc(w.name)}</option>`).join("")}</select>
      <button class="btn btn-icon" data-action="new-workspace" title="New workspace">＋</button>
      <div class="top-spacer"></div>
      <button class="btn btn-ghost" data-action="search" title="Global search (Ctrl+K)">⌕ <span>Search</span><span class="kbd">Ctrl K</span></button>
      <select class="select" id="environment-select" title="Active environment"><option value="">No environment</option>${environmentsForWorkspace().map((e:AnyRecord)=>`<option value="${e.id}" ${e.id===state.settings.activeEnvironmentId?"selected":""}>${esc(e.name)}</option>`).join("")}</select>
      <button class="btn btn-icon" data-action="environments" title="Manage environments">◈</button>
      <button class="btn btn-icon" data-action="settings" title="Settings">⚙</button>
      <div class="window-controls"><button class="window-control" data-action="window-minimise" title="Minimize">−</button><button class="window-control" data-action="window-maximise" title="Maximize or restore">□</button><button class="window-control close" data-action="window-close" title="Close">×</button></div>
    </header>
    <div class="shell-body"><aside class="sidebar"><div class="sidebar-top"><button class="btn btn-primary" data-action="${sidebarMode==="flows"?"new-flow":"new-rest"}">＋ ${sidebarMode==="flows"?"New flow":"New request"}</button><button class="btn btn-icon" data-action="${sidebarMode==="flows"?"new-flow":"new-soap"}" title="${sidebarMode==="flows"?"New flow":"New SOAP request"}">${sidebarMode==="flows"?"⌁":"◇"}</button></div><div class="sidebar-tabs"><button data-side="collections" class="${sidebarMode==="collections"?"active":""}">Collections</button><button data-side="flows" class="${sidebarMode==="flows"?"active":""}">Flows</button><button data-side="history" class="${sidebarMode==="history"?"active":""}">History</button></div><div id="sidebar-content" class="sidebar-content"></div></aside>
      <main class="workarea"><div id="tabs" class="tabs"></div><section id="workspace" class="workspace"></section></main></div>
    <footer class="statusbar"><span>● Local mode</span><span>SQLite</span><span class="right">${esc(state.goVersion)} · build ${esc(state.commit)}</span></footer>
  </div>`;
  renderSidebar(); renderTabs(); renderWorkspace();
}

function renderSidebar() {
  const host = document.querySelector<HTMLDivElement>("#sidebar-content"); if (!host) return;
  if (sidebarMode === "history") { host.innerHTML = renderHistory(); return; }
  if (sidebarMode === "flows") { host.innerHTML = renderFlowSidebar(); return; }
  const collections = collectionsForWorkspace();
  host.innerHTML = `<div class="sidebar-section-title"><span>Collections</span><span class="spacer"></span><button class="btn btn-ghost btn-sm" data-action="new-collection" title="New collection">＋</button></div>
    ${collections.length ? collections.map((collection: AnyRecord) => {
      const folders = (state.folders||[]).filter((f:AnyRecord)=>f.collectionId===collection.id);
      const direct = requestsForWorkspace().filter((r:AnyRecord)=>r.collectionId===collection.id&&!r.folderId);
      const collectionKey=`collection:${collection.id}`;const collectionCollapsed=collapsedTree.has(collectionKey);
      const children=direct.map((request:AnyRecord)=>renderRequestRow(request,false)).join("")+folders.map((folder:AnyRecord)=>renderFolderRow(folder,collection.id)).join("");
      return `<div class="tree-row" data-tree-kind="collection" data-tree-id="${collection.id}" data-drop-collection="${collection.id}"><button class="tree-toggle" data-action="toggle-tree" data-kind="collection" data-id="${collection.id}" title="${collectionCollapsed?"Expand":"Collapse"}">${collectionCollapsed?"▸":"▾"}</button><span>▱</span><span class="label">${esc(collection.name)}</span><button class="btn btn-ghost btn-sm" data-action="tree-menu" data-kind="collection" data-id="${collection.id}" title="Create or manage">＋</button></div>${collectionCollapsed?"":children}`;
    }).join("") : `<div class="muted" style="padding:18px 9px">No collections yet.<br>Create one to organize your requests.</div>`}
    <div class="sidebar-section-title"><span>Quick actions</span></div>
    <div class="tree-row" data-action="import-curl"><span>↳</span><span class="label">Import cURL</span></div>
    <div class="tree-row" data-action="import-wsdl"><span>◇</span><span class="label">Import WSDL</span></div>`;
}

function renderFlowSidebar(){const flows=flowsForWorkspace();return `<div class="sidebar-section-title"><span>Execution flows</span><span class="spacer"></span><button class="btn btn-ghost btn-sm" data-action="new-flow" title="New flow">＋</button></div>${flows.length?flows.map((flow:AnyRecord)=>`<div class="tree-row ${flow.id===activeFlowId?"active":""}" data-open-flow="${flow.id}"><span class="flow-list-icon">⌁</span><span class="label"><strong>${esc(flow.name)}</strong><br><small class="muted">${flow.nodes?.length||0} steps · ${flow.edges?.length||0} connections</small></span><button class="btn btn-ghost btn-sm" data-delete-flow="${flow.id}" title="Delete flow">×</button></div>`).join(""):`<div class="muted" style="padding:18px 9px">No flows yet.<br>Create one and chain your saved requests.</div>`}<div class="flow-sidebar-help"><strong>Response → next request</strong><span>Extract a JSON field into a variable, then use <code>{{variable}}</code> in a later request.</span></div>`}

function renderFolderRow(folder:AnyRecord,collectionId:string){const folderCollapsed=collapsedTree.has(`folder:${folder.id}`);const requests=requestsForWorkspace().filter((request:AnyRecord)=>request.folderId===folder.id);const children=folderCollapsed?"":`<div class="folder-children">${requests.map((request:AnyRecord)=>renderRequestRow(request,true)).join("")}</div>`;return `<div class="tree-row" style="padding-left:22px" data-tree-kind="folder" data-tree-id="${folder.id}" data-folder-drag="${folder.id}" data-drop-folder="${folder.id}" data-drop-collection="${collectionId}" draggable="true"><button class="tree-toggle" data-action="toggle-tree" data-kind="folder" data-id="${folder.id}" title="${folderCollapsed?"Expand":"Collapse"}">${folderCollapsed?"▸":"▾"}</button><span>▰</span><span class="label">${esc(folder.name)}</span><button class="btn btn-ghost btn-sm" data-action="tree-menu" data-kind="folder" data-id="${folder.id}" title="Create or manage">＋</button></div>${children}`}

function renderRequestRow(request: AnyRecord,nested=false) {
  return `<div class="tree-row ${request.id===activeId?"active":""}" style="padding-left:${nested?"14px":"22px"}" data-open-request="${request.id}" data-tree-kind="request" data-tree-id="${request.id}" draggable="true"><span class="method ${methodClass(request)}">${methodClass(request)}</span><span class="label">${esc(request.name)}</span></div>`;
}

function renderHistory() {
  const rows = (state.history||[]).filter((h:AnyRecord)=>h.workspaceId===activeWorkspace());
  return `<div class="sidebar-section-title"><span>Recent requests</span><span class="spacer"></span>${rows.length?`<button class="btn btn-ghost btn-sm" data-action="clear-history">Clear</button>`:""}</div>${rows.length?rows.map((h:AnyRecord)=>`<div class="tree-row" data-history="${h.id}"><span class="method ${h.method}">${esc(h.method)}</span><span class="label"><span>${esc(h.name)}</span><br><small class="muted">${new Date(h.executedAt).toLocaleString()}</small></span><strong class="status-code s${String(h.statusCode)[0]}">${h.statusCode}</strong></div>`).join(""):`<div class="muted" style="padding:18px 9px">Executed requests will appear here.</div>`}`;
}

function renderTabs() {
  const host = document.querySelector<HTMLDivElement>("#tabs"); if (!host) return;
  const flow=activeFlow();const flowTab=flow?`<div class="tab flow-tab active" data-flow-tab="${flow.id}"><span class="method FLOW">FLOW</span><span class="title">${esc(flow.name)}</span>${dirtyFlows.has(flow.id)?'<span class="dirty">●</span>':""}<button class="btn btn-ghost btn-sm" data-close-flow-tab="${flow.id}" title="Close">×</button></div>`:"";host.innerHTML = tabs.map(id => { const draft = drafts.get(id); if (!draft) return ""; const r=draft.data; return `<div class="tab ${!activeFlowId&&id===activeId?"active":""}" data-tab="${id}"><span class="method ${methodClass(r)}">${methodClass(r)}</span><span class="title">${esc(r.name)}</span>${draft.dirty?'<span class="dirty">●</span>':""}<button class="btn btn-ghost btn-sm" data-close-tab="${id}" title="Close">×</button></div>`; }).join("") + flowTab + `<button class="tab-add" data-action="new-rest" title="New request">＋</button>`;
}

function renderWorkspace() {
  const host=document.querySelector<HTMLDivElement>("#workspace");if(!host)return;if(activeFlowId){const flow=activeFlow();host.innerHTML=flow?renderFlowEditor(flow):renderWelcome();return}const request=activeRequest();
  if(!request){host.innerHTML=renderWelcome();return}
  host.innerHTML=`<div class="request-view">
    <div class="request-namebar"><input class="request-name" data-bind="name" value="${esc(request.name)}" aria-label="Request name"><span class="badge">${esc(request.protocol)}</span><span class="spacer"></span>${!request.verifySsl?'<span class="badge warn">⚠ SSL verification off</span>':''}<select class="select" data-bind="collectionId"><option value="">No collection</option>${collectionsForWorkspace().map((c:AnyRecord)=>`<option value="${c.id}" ${c.id===request.collectionId?"selected":""}>${esc(c.name)}</option>`).join("")}</select><button class="btn" data-action="duplicate-request">Duplicate</button><button class="btn" data-action="copy-curl">Copy as cURL</button><button class="btn" data-action="save-request">Save <span class="kbd">Ctrl S</span></button></div>
    <div class="request-bar"><select class="select method-select ${methodClass(request)}" data-bind="method" ${request.protocol==="SOAP"?"disabled":""}>${["GET","POST","PUT","PATCH","DELETE","HEAD","OPTIONS"].map(m=>`<option ${m===request.method?"selected":""}>${m}</option>`).join("")}</select><input class="input url-input" id="url-input" value="${esc(urlWithParams(request))}" placeholder="https://{{baseUrl}}/api/v1/resource"><button class="btn btn-primary" data-action="${sendingId===activeId?"cancel-request":"send-request"}">${sendingId===activeId?"■ Cancel":"▶ Send"} <span class="kbd">Ctrl ↵</span></button></div>
    <div class="split ${state.settings.responsePaneCollapsed?"response-collapsed":""}"><section class="pane"><div class="subtabs">${requestTabs(request).map(([id,label])=>`<button data-request-tab="${id}" class="${requestTab===id?"active":""}">${label}${countBadge(request,id)}</button>`).join("")}</div><div id="request-pane" class="pane-body">${renderRequestPane(request)}</div></section><div class="splitter" id="splitter"><button class="pane-toggle" data-action="toggle-response-pane" title="${state.settings.responsePaneCollapsed?"Restore response panel":"Collapse response panel"}">${state.settings.responsePaneCollapsed?"⌃":"⌄"}</button></div><section class="pane" id="response-pane">${renderResponse(request)}</section></div>
  </div>`;
  installSplitter();
}

function renderWelcome(){return `<div class="welcome"><div class="welcome-card"><div class="forge-mark">M</div><h1>Build, test and automate your APIs.</h1><p>REST, SOAP, load tests and visual execution flows. Your work stays on this machine.</p><div class="welcome-actions"><button class="btn btn-primary" data-action="new-rest">＋ New REST Request</button><button class="btn" data-action="new-soap">◇ New SOAP Request</button><button class="btn" data-action="new-flow">⌁ New Flow</button></div><div class="import-row">Import an existing definition<br><br><button class="btn" data-action="import-curl">cURL</button> <button class="btn" data-action="import-wsdl">WSDL</button></div></div></div>`}

function flowNodeType(node:AnyRecord){return String(node.type||"request").toLowerCase()}
function flowNodeWidth(){return 236}
function flowInputY(node:AnyRecord){return 50}
function flowOutputHandles(node:AnyRecord):string[]{
  const type=flowNodeType(node);
  if(type==="if")return ["true","false"];
  if(type==="loop")return ["done","loop"];
  if(type==="switch"){const count=(node.switchMode||"rules")==="expression"?Math.max(2,Number(node.switchOutputs)||2):Math.max(1,(node.switchRules||[]).length);return Array.from({length:count},(_,i)=>String(i))}
  if(type==="parallel")return Array.from({length:Math.max(2,Number(node.parallelBranches)||2)},(_,i)=>String(i));
  return ["default"];
}
function flowOutputY(node:AnyRecord,handle="default"){
  const handles=flowOutputHandles(node);const index=Math.max(0,handles.indexOf(String(handle)));
  if(handles.length===1)return 50;
  return 38+index*28;
}
function flowNodeHeight(node:AnyRecord){return Math.max(100,50+flowOutputHandles(node).length*28)}
function flowNodeIcon(type:string){return type==="if"?"⇄":type==="filter"?"⏷":type==="extract"?"{}":type==="loop"?"↻":type==="wait"?"⌛":type==="switch"?"⇶":type==="parallel"?"⋔":"↯"}
function flowNodeLabel(type:string){return type==="if"?"If":type==="filter"?"Filter":type==="extract"?"Extract Data":type==="loop"?"Loop Over Items":type==="wait"?"Wait":type==="switch"?"Switch":type==="parallel"?"Parallel":"Request"}

function renderFlowEditor(flow:AnyRecord){
  if(selectedFlowNodeId&&!flow.nodes.some((node:AnyRecord)=>node.id===selectedFlowNodeId))selectedFlowNodeId="";
  const result=flowResults.get(flow.id);
  return `<div class="flow-view">
    <div class="flow-toolbar">
      <input class="request-name flow-name" data-flow-name value="${esc(flow.name)}" aria-label="Flow name">
      <span class="badge">FLOW</span>
      <span class="muted">Use + to add the next node · drag handles to connect manually</span>
      <span class="spacer"></span>
      ${result?`<span class="flow-run-summary ${result.successful?"success":"failed"}">${result.successful?"✓ Completed":"× Failed"} · ${result.durationMs} ms</span>`:""}
      <button class="btn" data-action="add-flow-node">＋ Node</button>
      <button class="btn" data-action="save-flow">Save <span class="kbd">Ctrl S</span></button>
      <button class="btn btn-primary" data-action="run-flow" ${flowRunningId===flow.id||!flow.nodes.length?"disabled":""}>${flowRunningId===flow.id?"Running…":"▶ Run flow"}</button>
    </div>
    <div class="flow-layout">
      <div class="flow-canvas-wrap">
        <div class="flow-canvas" id="flow-canvas">
          <svg class="flow-connections" id="flow-connections">${renderFlowEdges(flow)}<path id="flow-preview-edge" class="flow-edge preview" d="" hidden></path></svg>
          ${flow.nodes.length?flow.nodes.map((node:AnyRecord)=>renderFlowNode(flow,node,result)).join(""):`<button class="flow-empty" data-action="add-flow-node"><strong>＋ Add your first node</strong><span>Choose a saved request or a Flow function.</span></button>`}
        </div>
      </div>
      <aside class="flow-inspector">${renderFlowInspector(flow,result)}</aside>
    </div>
  </div>`;
}

function renderFlowEdges(flow:AnyRecord){
  return (flow.edges||[]).map((edge:AnyRecord)=>{
    const source=flow.nodes.find((node:AnyRecord)=>node.id===edge.sourceId);
    const target=flow.nodes.find((node:AnyRecord)=>node.id===edge.targetId);
    if(!source||!target)return "";
    const handle=edge.sourceHandle||"default";
    const branchClass=handle==="true"?" true":handle==="false"?" false":"";
    const live=flowLiveEdges.get(edge.id);const liveClass=live?.status==="running"?" running":live?.status==="completed"?" passed":"";
    return `<path data-flow-edge="${edge.id}" class="flow-edge${branchClass}${liveClass}" d="${flowEdgePath(source.x+flowNodeWidth(),source.y+flowOutputY(source,handle),target.x,target.y+flowInputY(target))}"></path>`;
  }).join("");
}

function flowEdgePath(x1:number,y1:number,x2:number,y2:number){
  const bend=Math.max(55,Math.abs(x2-x1)*.45);
  return `M ${x1} ${y1} C ${x1+bend} ${y1}, ${x2-bend} ${y2}, ${x2} ${y2}`;
}

function renderFlowNode(flow:AnyRecord,node:AnyRecord,result:AnyRecord){
  const type=flowNodeType(node);
  const request=type==="request"?state.requests.find((item:AnyRecord)=>item.id===node.requestId):null;
  const execution=result?.nodes?.filter((item:AnyRecord)=>item.nodeId===node.id).at(-1);
  const live=flowLiveNodes.get(node.id);
  const status=live?.status==="running"?"running":live?.status==="completed"?"success":live?.status==="failed"?"failed":execution?.skipped?"skipped":execution?(execution.error?"failed":"success"):(flowRunningId===flow.id?"waiting":"idle");
  const title=type==="request"?(node.name||request?.name||"Missing request"):(node.name||flowNodeLabel(type));
  const headBadge=type==="request"?`<span class="method ${request?methodClass(request):"DELETE"}">${request?methodClass(request):"?"}</span>`:`<span class="flow-function-icon ${type}">${flowNodeIcon(type)}</span>`;
  let body="";
  if(type==="request"){
    body=`<span>${request?esc(request.url||"No URL"):"Saved request was deleted"}</span><small>${node.mappings?.length||0} response variable${node.mappings?.length===1?"":"s"}</small>`;
  }else if(type==="if"){
    body=`<span>Conditional branch</span><small>${node.conditions?.length||0} condition${node.conditions?.length===1?"":"s"} · ${(node.match||"all")==="any"?"ANY":"ALL"}</small>`;
  }else if(type==="filter"){
    body=`<span>Continue only when matched</span><small>${node.conditions?.length||0} condition${node.conditions?.length===1?"":"s"}</small>`;
  }else if(type==="extract"){
    body=`<span>Extract values into variables</span><small>${node.mappings?.length||0} value${node.mappings?.length===1?"":"s"}</small>`;
  }else if(type==="loop"){body=`<span>Repeat connected loop branch</span><small>${Math.max(1,Number(node.loopCount)||1)} iteration(s)</small>`}
  else if(type==="wait"){body=`<span>Pause execution</span><small>${node.waitValue||0} ${esc(node.waitUnit||"ms")}</small>`}
  else if(type==="switch"){body=`<span>Route to one output</span><small>mode: ${esc(node.switchMode||"rules")}</small>`}
  else if(type==="parallel"){body=`<span>Run branches concurrently</span><small>${Math.max(2,Number(node.parallelBranches)||2)} branches</small>`}
  const handles=flowOutputHandles(node);
  const outputs=handles.map((handle)=>{const label=handles.length>1?`<div class="flow-branch-label dynamic" style="top:${flowOutputY(node,handle)-8}px">${esc(handle)}</div>`:"";return `${label}<button class="flow-handle output dynamic" style="top:${flowOutputY(node,handle)-8}px" data-flow-output="${node.id}" data-flow-handle="${esc(handle)}" title="${esc(handle)} output"></button><button class="flow-add-next dynamic" style="top:${flowOutputY(node,handle)-12}px" data-flow-add-after="${node.id}" data-flow-add-handle="${esc(handle)}" title="Add next node">＋</button>`}).join("");
  return `<article class="flow-node type-${type} ${node.id===selectedFlowNodeId?"selected":""} ${status}" data-flow-node="${node.id}" style="left:${node.x}px;top:${node.y}px;height:${flowNodeHeight(node)}px">
    <button class="flow-handle input" data-flow-input="${node.id}" title="Connect into this step"></button>
    <div class="flow-node-head" data-flow-node-drag="${node.id}">${headBadge}<strong>${esc(title)}</strong><span class="flow-node-state">${status==="running"?`▶${live?.iteration?` ${live.iteration}`:""}`:status==="success"?(execution?.outcome&&execution.outcome!=="success"?esc(execution.outcome):"✓"):status==="failed"?"!":status==="skipped"?"–":""}</span></div>
    <div class="flow-node-body">${body}</div>
    ${outputs}
  </article>`;
}

function renderFlowInspector(flow:AnyRecord,result:AnyRecord){
  const node=flow.nodes.find((item:AnyRecord)=>item.id===selectedFlowNodeId);
  if(!node)return `<div class="flow-inspector-empty"><div>⌁</div><strong>Select a step</strong><p>Configure requests, conditions, filters and extracted variables.</p><p>Use the <strong>＋</strong> at the end of a node to add the next step.</p></div>`;
  const execution=result?.nodes?.filter((item:AnyRecord)=>item.nodeId===node.id).at(-1);
  const type=flowNodeType(node);
  const related=(flow.edges||[]).filter((edge:AnyRecord)=>edge.sourceId===node.id||edge.targetId===node.id);
  let body="";
  if(type==="request")body=renderRequestFlowInspector(node);
  if(type==="if"||type==="filter")body=renderConditionFlowInspector(node,type);
  if(type==="extract")body=renderExtractFlowInspector(node);
  if(type==="loop")body=renderLoopFlowInspector(node);
  if(type==="wait")body=renderWaitFlowInspector(node);
  if(type==="switch")body=renderSwitchFlowInspector(node);
  if(type==="parallel")body=renderParallelFlowInspector(node);
  return `<div class="flow-inspector-head"><div><span class="muted">${type==="request"?"REQUEST":"FLOW FUNCTION"}</span><h3>${esc(node.name||flowNodeLabel(type))}</h3></div><button class="btn btn-ghost btn-sm btn-danger" data-delete-flow-node="${node.id}">Delete</button></div>${body}${related.length?renderFlowConnections(flow,node,related):""}${execution?renderFlowNodeResult(execution):""}`;
}

function renderRequestFlowInspector(node:AnyRecord){
  const mappings=[...(node.mappings||[]),{path:"",variable:""}];
  return `<div class="field"><label>Saved request</label><select class="select" data-flow-node-request="${node.id}">${requestsForWorkspace().map((request:AnyRecord)=>`<option value="${request.id}" ${request.id===node.requestId?"selected":""}>${esc(request.name)} · ${methodClass(request)}</option>`).join("")}</select></div>
    <div class="flow-help"><strong>Export values from this response</strong><span>JSON path supports dots and arrays. Special paths: <code>status</code>, <code>body</code>, <code>headers.Name</code>.</span></div>
    ${renderFlowMappings(node,mappings,"client.nrCliente","nrCliente")}`;
}

function renderExtractFlowInspector(node:AnyRecord){
  const mappings=[...(node.mappings||[]),{path:"",variable:""}];
  return `<div class="flow-help no-border"><strong>Extract data</strong><span>Read from the last response in this branch and store values as variables for later nodes.</span><span>Examples: <code>body.client.id</code>, <code>status</code>, <code>headers.Location</code> or <code>variables.token</code>.</span></div>${renderFlowMappings(node,mappings,"body.client.id","clientId")}`;
}

function renderFlowMappings(node:AnyRecord,mappings:AnyRecord[],pathPlaceholder:string,variablePlaceholder:string){
  return `<div class="flow-mappings">${mappings.map((mapping:AnyRecord,index:number)=>`<div class="flow-mapping"><input class="input" data-flow-map-field="path" data-flow-map-node="${node.id}" data-flow-map-index="${index}" value="${esc(mapping.path)}" placeholder="${pathPlaceholder}"><span>→</span><input class="input" data-flow-map-field="variable" data-flow-map-node="${node.id}" data-flow-map-index="${index}" value="${esc(mapping.variable)}" placeholder="${variablePlaceholder}">${index<(node.mappings||[]).length?`<button class="btn btn-ghost btn-sm" data-remove-flow-map="${node.id}" data-index="${index}">×</button>`:"<span></span>"}</div>`).join("")}</div>`;
}

function renderConditionFlowInspector(node:AnyRecord,type:string){
  const conditions=node.conditions||[];
  const operatorOptions=[
    ["equals","is equal to"],["not_equals","is not equal to"],["contains","contains"],["not_contains","does not contain"],
    ["starts_with","starts with"],["ends_with","ends with"],["greater_than","is greater than"],["greater_or_equal","is greater or equal"],
    ["less_than","is less than"],["less_or_equal","is less or equal"],["exists","exists"],["not_exists","does not exist"],
    ["empty","is empty"],["not_empty","is not empty"],["regex","matches regex"]
  ];
  return `<div class="flow-function-summary"><span class="flow-function-icon ${type}">${flowNodeIcon(type)}</span><div><strong>${flowNodeLabel(type)}</strong><span>${type==="if"?"Route execution to true or false branches.":"Continue the branch only when the condition matches."}</span></div></div>
    <div class="field-grid flow-condition-settings"><div class="field"><label>Match</label><select class="select" data-flow-condition-match="${node.id}"><option value="all" ${(node.match||"all")==="all"?"selected":""}>All conditions</option><option value="any" ${node.match==="any"?"selected":""}>Any condition</option></select></div></div>
    <div class="flow-help no-border"><strong>Conditions</strong><span>Use response paths such as <code>status</code> or <code>body.customer.id</code>, variables like <code>{{customerId}}</code>, or literal values.</span></div>
    <div class="flow-conditions">${conditions.length?conditions.map((condition:AnyRecord,index:number)=>`<div class="flow-condition-row"><input class="input" data-flow-condition-field="left" data-flow-condition-node="${node.id}" data-flow-condition-index="${index}" value="${esc(condition.left)}" placeholder="status"><select class="select" data-flow-condition-field="operator" data-flow-condition-node="${node.id}" data-flow-condition-index="${index}">${operatorOptions.map(([value,label])=>`<option value="${value}" ${condition.operator===value?"selected":""}>${label}</option>`).join("")}</select><input class="input" data-flow-condition-field="right" data-flow-condition-node="${node.id}" data-flow-condition-index="${index}" value="${esc(condition.right)}" placeholder="200"><button class="btn btn-ghost btn-sm" data-remove-flow-condition="${node.id}" data-index="${index}">×</button></div>`).join(""):'<div class="muted flow-no-conditions">No conditions configured.</div>'}</div>
    <button class="btn btn-sm" data-add-flow-condition="${node.id}">＋ Add condition</button>
    <label class="flow-toggle"><input type="checkbox" data-flow-convert-types="${node.id}" ${node.convertTypes?"checked":""}><span>Convert types where required</span></label>`;
}

function renderLoopFlowInspector(node:AnyRecord){
  return `<div class="flow-function-summary"><span class="flow-function-icon loop">↻</span><div><strong>Loop Over Items</strong><span>Execute the loop branch a fixed number of times, then continue through done.</span></div></div><div class="field"><label>Number of executions</label><input class="input" type="number" min="1" max="10000" data-flow-loop-count="${node.id}" value="${Math.max(1,Number(node.loopCount)||1)}"></div><div class="flow-help"><strong>Loop wiring</strong><span>Add nodes from the <code>loop</code> output. Connect the last node of the body back to this Loop input. After the counter finishes, the <code>done</code> output continues.</span></div>`;
}
function renderWaitFlowInspector(node:AnyRecord){
  return `<div class="flow-function-summary"><span class="flow-function-icon wait">⌛</span><div><strong>Wait</strong><span>Pause this branch before continuing.</span></div></div><div class="field-grid"><div class="field"><label>Time</label><input class="input" type="number" min="0" step="0.1" data-flow-wait-value="${node.id}" value="${Number(node.waitValue)||0}"></div><div class="field"><label>Unit</label><select class="select" data-flow-wait-unit="${node.id}"><option value="ms" ${(node.waitUnit||"ms")==="ms"?"selected":""}>milliseconds (ms)</option><option value="s" ${node.waitUnit==="s"?"selected":""}>seconds (s)</option><option value="min" ${node.waitUnit==="min"?"selected":""}>minutes (min)</option></select></div></div>`;
}
function renderSwitchFlowInspector(node:AnyRecord){
  const mode=node.switchMode||"rules";const rules=node.switchRules||[];const ops=[["equals","is equal to"],["not_equals","is not equal to"],["contains","contains"],["not_contains","does not contain"],["starts_with","starts with"],["ends_with","ends with"],["greater_than","is greater than"],["greater_or_equal","is greater or equal"],["less_than","is less than"],["less_or_equal","is less or equal"],["exists","exists"],["not_exists","does not exist"],["empty","is empty"],["not_empty","is not empty"],["regex","matches regex"]];
  return `<div class="flow-function-summary"><span class="flow-function-icon switch">⇶</span><div><strong>Switch</strong><span>Route execution to one of several outputs.</span></div></div><div class="field"><label>Mode</label><select class="select" data-flow-switch-mode="${node.id}"><option value="rules" ${mode==="rules"?"selected":""}>Rules</option><option value="expression" ${mode==="expression"?"selected":""}>Expression</option></select></div>${mode==="expression"?`<div class="field"><label>Number of outputs</label><input class="input" type="number" min="2" max="20" data-flow-switch-outputs="${node.id}" value="${Math.max(2,Number(node.switchOutputs)||2)}"></div><div class="field"><label>Output index expression</label><input class="input" data-flow-switch-expression="${node.id}" value="${esc(node.switchExpression||"0")}" placeholder="{{routeIndex}}"></div>`:`<div class="flow-help no-border"><strong>Routing rules</strong><span>The first matching rule selects its numbered output.</span></div><div class="flow-switch-rules">${rules.map((rule:AnyRecord,index:number)=>`<div class="flow-condition-row"><input class="input" data-flow-switch-rule-field="left" data-flow-switch-rule-node="${node.id}" data-flow-switch-rule-index="${index}" value="${esc(rule.left)}" placeholder="status"><select class="select" data-flow-switch-rule-field="operator" data-flow-switch-rule-node="${node.id}" data-flow-switch-rule-index="${index}">${ops.map(([v,l])=>`<option value="${v}" ${rule.operator===v?"selected":""}>${l}</option>`).join("")}</select><input class="input" data-flow-switch-rule-field="right" data-flow-switch-rule-node="${node.id}" data-flow-switch-rule-index="${index}" value="${esc(rule.right)}" placeholder="200"><button class="btn btn-ghost btn-sm" data-remove-flow-switch-rule="${node.id}" data-index="${index}">×</button></div>`).join("")}</div><button class="btn btn-sm" data-add-flow-switch-rule="${node.id}">＋ Add routing rule</button>`}`;
}
function renderParallelFlowInspector(node:AnyRecord){
  return `<div class="flow-function-summary"><span class="flow-function-icon parallel">⋔</span><div><strong>Parallel</strong><span>Start two or more independent branches at the same time.</span></div></div><div class="field"><label>Parallel branches</label><input class="input" type="number" min="2" max="10" data-flow-parallel-branches="${node.id}" value="${Math.max(2,Number(node.parallelBranches)||2)}"></div><div class="flow-help"><strong>Execution</strong><span>Each numbered output is started concurrently. The flow run finishes after all parallel branches finish.</span></div>`;
}

function renderFlowConnections(flow:AnyRecord,node:AnyRecord,related:AnyRecord[]){
  return `<div class="flow-help"><strong>Connections</strong>${related.map((edge:AnyRecord)=>{const other=flow.nodes.find((item:AnyRecord)=>item.id===(edge.sourceId===node.id?edge.targetId:edge.sourceId));const branch=edge.sourceId===node.id&&edge.sourceHandle?` · ${edge.sourceHandle}`:"";return `<div class="flow-connection-row"><span>${edge.sourceId===node.id?"To":"From"} ${esc(other?.name||"step")}${esc(branch)}</span><button class="btn btn-ghost btn-sm" data-remove-flow-edge="${edge.id}">×</button></div>`}).join("")}</div>`;
}

function renderFlowNodeResult(execution:AnyRecord){
  if(execution.skipped)return `<div class="flow-node-result"><h4>Last execution</h4><div class="flow-result-metrics"><span class="badge">Skipped</span><span>Branch was not selected</span></div></div>`;
  const response=execution.response||{};
  let body=response.body||"";
  if(body.length>5000)body=body.slice(0,5000)+"\n…";
  return `<div class="flow-node-result"><h4>Last execution</h4><div class="flow-result-metrics">${response.statusCode?`<span class="status-code s${String(response.statusCode||0)[0]}">${response.statusCode}</span>`:""}${execution.outcome?`<span class="badge">${esc(execution.outcome)}</span>`:""}<span>${response.durationMs||0} ms</span>${execution.iteration?`<span class="badge">iteration ${execution.iteration}</span>`:""}</div>${execution.error?`<div class="flow-error">${esc(execution.error)}</div>`:""}${Object.keys(execution.extracted||{}).length?`<div class="flow-extracted">${Object.entries(execution.extracted).map(([key,value])=>`<div><code>${esc(key)}</code><span>${esc(value)}</span></div>`).join("")}</div>`:""}${body?`<pre>${esc(body)}</pre>`:""}</div>`;
}

async function createFlow(){
  showModal("New execution flow",`<div class="field"><label>Flow name</label><input class="input" id="flow-new-name" style="width:100%" value="Untitled flow" autofocus></div><p class="muted">After creating it, use + to add requests and Flow functions.</p>`,[
    {label:"Cancel",action:closeModal},
    {label:"Create flow",primary:true,action:async()=>{
      const name=(document.querySelector<HTMLInputElement>("#flow-new-name")?.value||"Untitled flow").trim();
      try{
        const saved=await api("SaveFlow",{id:"",workspaceId:activeWorkspace(),name,nodes:[],edges:[],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});
        state.flows.unshift(saved);activeFlowId=saved.id;activeId="";selectedFlowNodeId="";sidebarMode="flows";closeModal();renderShell();
      }catch(error){toast(String(error),true)}
    }}
  ]);
}

function openFlow(id:string){
  if(activeRequest())syncVisibleFields();
  activeFlowId=id;activeId="";selectedFlowNodeId=activeFlow()?.nodes?.[0]?.id||"";sidebarMode="flows";renderShell();
}

async function persistFlow(showToast=true){
  const flow=activeFlow();
  if(!flow)return null;
  flow.nodes.forEach((node:AnyRecord)=>{
    node.type=flowNodeType(node);
    node.mappings=(node.mappings||[]).filter((mapping:AnyRecord)=>mapping.path?.trim()&&mapping.variable?.trim());
    node.conditions=(node.conditions||[]).filter((condition:AnyRecord)=>condition.left?.trim());
    node.match=node.match||"all";
  });
  try{
    const saved=await api("SaveFlow",flow);
    const index=state.flows.findIndex((item:AnyRecord)=>item.id===saved.id);
    if(index>=0)state.flows[index]=saved;
    dirtyFlows.delete(saved.id);
    if(showToast)toast("Flow saved");
    renderTabs();renderSidebar();
    return saved;
  }catch(error){
    toast(`Could not save flow: ${error}`,true);
    return null;
  }
}

function showFlowNodePicker(sourceId="",sourceHandle="default"){
  const requests=requestsForWorkspace();
  flowPendingAdd={sourceId,sourceHandle};
  const requestItems=requests.map((request:AnyRecord)=>`<button class="flow-palette-item" data-flow-palette-item data-flow-pick-request="${request.id}" data-search-text="${esc(`${request.name} ${request.url} ${methodClass(request)}`.toLowerCase())}"><span class="method ${methodClass(request)}">${methodClass(request)}</span><span><strong>${esc(request.name)}</strong><small>${esc(request.url||"No URL")}</small></span><span>→</span></button>`).join("");
  showModal("Add next node",`<div class="flow-palette"><div class="flow-palette-search"><span>⌕</span><input class="input" id="flow-node-search" placeholder="Search nodes..." autofocus></div><div class="flow-palette-section"><h4>Flow</h4><button class="flow-palette-item" data-flow-palette-item data-flow-pick-type="if" data-search-text="if conditional condition branch"><span class="flow-function-icon if">⇄</span><span><strong>If</strong><small>Route execution to true / false branches</small></span><span>→</span></button><button class="flow-palette-item" data-flow-palette-item data-flow-pick-type="filter" data-search-text="filter condition"><span class="flow-function-icon filter">⏷</span><span><strong>Filter</strong><small>Continue only when a condition matches</small></span><span>→</span></button><button class="flow-palette-item" data-flow-palette-item data-flow-pick-type="extract" data-search-text="extract data variable json"><span class="flow-function-icon extract">{}</span><span><strong>Extract Data</strong><small>Extract response data into variables</small></span><span>→</span></button><button class="flow-palette-item" data-flow-palette-item data-flow-pick-type="loop" data-search-text="loop repeat counter iteration"><span class="flow-function-icon loop">↻</span><span><strong>Loop Over Items</strong><small>Repeat a branch using a configured counter</small></span><span>→</span></button><button class="flow-palette-item" data-flow-palette-item data-flow-pick-type="wait" data-search-text="wait delay sleep ms seconds minutes"><span class="flow-function-icon wait">⌛</span><span><strong>Wait</strong><small>Pause execution in ms, seconds or minutes</small></span><span>→</span></button><button class="flow-palette-item" data-flow-palette-item data-flow-pick-type="switch" data-search-text="switch route rules expression"><span class="flow-function-icon switch">⇶</span><span><strong>Switch</strong><small>Route to multiple outputs by rules or expression</small></span><span>→</span></button><button class="flow-palette-item" data-flow-palette-item data-flow-pick-type="parallel" data-search-text="parallel concurrent branches"><span class="flow-function-icon parallel">⋔</span><span><strong>Parallel</strong><small>Run multiple branches concurrently</small></span><span>→</span></button></div><div class="flow-palette-section"><h4>Requests</h4>${requestItems||'<div class="muted" style="padding:10px">No saved requests in this workspace.</div>'}</div></div>`,[{label:"Close",action:()=>{flowPendingAdd=null;closeModal()}}],true);
}

function addFlowRequestNode(requestId:string){
  const flow=activeFlow();
  const request=state.requests.find((item:AnyRecord)=>item.id===requestId);
  if(!flow||!request)return;
  const source=flowPendingAdd?.sourceId?flow.nodes.find((node:AnyRecord)=>node.id===flowPendingAdd!.sourceId):null;
  const handle=flowPendingAdd?.sourceHandle||"default";
  const node={id:uid(),type:"request",requestId,name:request.name,...nextFlowNodePosition(flow,source,handle),mappings:[],conditions:[],match:"all",convertTypes:false};
  flow.nodes.push(node);
  connectNewFlowNode(flow,source,node,handle);
}

function addFlowFunctionNode(type:string){
  const flow=activeFlow();
  if(!flow)return;
  const source=flowPendingAdd?.sourceId?flow.nodes.find((node:AnyRecord)=>node.id===flowPendingAdd!.sourceId):null;
  const handle=flowPendingAdd?.sourceHandle||"default";
  const defaults:typeDefaults=flowFunctionDefaults(type);
  const node={id:uid(),type,requestId:"",...defaults,...nextFlowNodePosition(flow,source,handle),match:"all",convertTypes:true};
  flow.nodes.push(node);
  connectNewFlowNode(flow,source,node,handle);
}

type typeDefaults={name:string;mappings:AnyRecord[];conditions:AnyRecord[];[key:string]:any};
function flowFunctionDefaults(type:string):typeDefaults{
  if(type==="if")return {name:"If",mappings:[],conditions:[{left:"status",operator:"equals",right:"200"}]};
  if(type==="filter")return {name:"Filter",mappings:[],conditions:[{left:"status",operator:"less_than",right:"400"}]};
  if(type==="loop")return {name:"Loop Over Items",mappings:[],conditions:[],loopCount:3};
  if(type==="wait")return {name:"Wait",mappings:[],conditions:[],waitValue:1000,waitUnit:"ms"};
  if(type==="switch")return {name:"Switch",mappings:[],conditions:[],switchMode:"rules",switchRules:[{left:"status",operator:"equals",right:"200"},{left:"status",operator:"greater_or_equal",right:"400"}],switchOutputs:2,switchExpression:"0"};
  if(type==="parallel")return {name:"Parallel",mappings:[],conditions:[],parallelBranches:2};
  return {name:"Extract Data",mappings:[{path:"body.id",variable:"id"}],conditions:[]};
}

function nextFlowNodePosition(flow:AnyRecord,source:AnyRecord,handle:string){
  if(source){
    const handles=flowOutputHandles(source);const index=Math.max(0,handles.indexOf(handle));const yOffset=handles.length>1?(index-(handles.length-1)/2)*95:0;
    return {x:Math.min(1480,source.x+330),y:Math.max(20,Math.min(840,source.y+yOffset))};
  }
  return {x:90+Math.min(flow.nodes.length,4)*35,y:90+flow.nodes.length*110};
}

function connectNewFlowNode(flow:AnyRecord,source:AnyRecord,node:AnyRecord,handle:string){
  if(source)flow.edges.push({id:uid(),sourceId:source.id,targetId:node.id,sourceHandle:handle});
  selectedFlowNodeId=node.id;
  dirtyFlows.add(flow.id);
  flowPendingAdd=null;
  closeModal();
  renderTabs();renderSidebar();renderWorkspace();
}

function removeFlowNode(id:string){
  const flow=activeFlow();if(!flow)return;
  flow.nodes=flow.nodes.filter((node:AnyRecord)=>node.id!==id);
  flow.edges=flow.edges.filter((edge:AnyRecord)=>edge.sourceId!==id&&edge.targetId!==id);
  selectedFlowNodeId=flow.nodes[0]?.id||"";
  dirtyFlows.add(flow.id);renderTabs();renderSidebar();renderWorkspace();
}
function removeFlowEdge(id:string){const flow=activeFlow();if(!flow)return;flow.edges=flow.edges.filter((edge:AnyRecord)=>edge.id!==id);dirtyFlows.add(flow.id);renderTabs();renderSidebar();renderWorkspace()}
function removeFlowMapping(nodeId:string,index:number){const flow=activeFlow();const node=flow?.nodes.find((item:AnyRecord)=>item.id===nodeId);if(!node)return;node.mappings.splice(index,1);dirtyFlows.add(flow.id);renderTabs();renderWorkspace()}
function addFlowCondition(nodeId:string){const flow=activeFlow();const node=flow?.nodes.find((item:AnyRecord)=>item.id===nodeId);if(!node)return;node.conditions||=[];node.conditions.push({left:"",operator:"equals",right:""});dirtyFlows.add(flow.id);renderTabs();renderWorkspace()}
function removeFlowCondition(nodeId:string,index:number){const flow=activeFlow();const node=flow?.nodes.find((item:AnyRecord)=>item.id===nodeId);if(!node)return;node.conditions.splice(index,1);dirtyFlows.add(flow.id);renderTabs();renderWorkspace()}

function deleteFlow(id:string){
  const flow=(state.flows||[]).find((item:AnyRecord)=>item.id===id);if(!flow)return;
  showModal(`Delete ${flow.name}?`,`<p>This permanently removes the visual flow. Saved requests are not deleted.</p>`,[{label:"Cancel",action:closeModal},{label:"Delete flow",danger:true,action:async()=>{try{await api("DeleteEntity","flow",id);state.flows=state.flows.filter((item:AnyRecord)=>item.id!==id);dirtyFlows.delete(id);flowResults.delete(id);if(activeFlowId===id){activeFlowId="";selectedFlowNodeId=""}closeModal();renderShell();toast("Flow deleted")}catch(error){toast(String(error),true)}}}]);
}

async function runFlow(){
  const flow=await persistFlow(false);
  if(!flow||flowRunningId)return;
  flowRunningId=flow.id;flowResults.delete(flow.id);flowLiveNodes.clear();flowLiveEdges.clear();renderWorkspace();
  try{
    const result=await api("RunFlow",{executionId:uid(),flow,environmentId:state.settings.activeEnvironmentId||"",variables:{}});
    flowResults.set(flow.id,result);
    toast(result.successful?`Flow completed in ${result.durationMs} ms`:`Flow stopped at a failed step`,!result.successful);
  }catch(error){toast(`Flow could not run: ${error}`,true)}finally{flowRunningId="";renderWorkspace()}
}

function requestTabs(request:AnyRecord):[string,string][]{return request.protocol==="SOAP"?[["soap","SOAP"],["auth","Auth"],["headers","Headers"],["body","SOAP Body"],["load","Load Test"]]:[["params","Params"],["auth","Auth"],["headers","Headers"],["body","Body"],["load","Load Test"]]}
function countBadge(request:AnyRecord,id:string){const count=id==="params"?request.params?.filter((x:AnyRecord)=>x.enabled&&x.key).length:id==="headers"?request.headers?.filter((x:AnyRecord)=>x.enabled&&x.key).length:0;return count?` <span class="badge">${count}</span>`:""}

function renderRequestPane(request:AnyRecord){
  if(requestTab==="load")return renderLoadTest(request);
  if(requestTab==="params")return renderKeyValueTable("params",request.params||[],"Key","Value");
  if(requestTab==="headers")return renderKeyValueTable("headers",request.headers||[],"Header","Value");
  if(requestTab==="auth")return renderAuth(request);
  if(requestTab==="soap")return `<div class="field-grid"><div class="field"><label>SOAP version</label><select class="select" data-bind="soapVersion"><option value="1.1" ${request.soapVersion==="1.1"?"selected":""}>SOAP 1.1</option><option value="1.2" ${request.soapVersion==="1.2"?"selected":""}>SOAP 1.2</option></select></div><div class="field"><label>SOAPAction</label><input class="input" data-bind="soapAction" value="${esc(request.soapAction)}" placeholder="urn:GetCustomer"></div><div class="field wide"><label>Endpoint</label><input class="input" data-bind="url" value="${esc(request.url)}"></div></div><p class="muted">SOAP headers are generated automatically and can be overridden in the Headers tab.</p>`;
  return renderBody(request);
}

function renderLoadTest(request:AnyRecord){const config=loadConfigs.get(request.id)||{concurrency:5,totalRequests:50,delayMs:0};loadConfigs.set(request.id,config);const history=(state.loadTests||[]).filter((run:AnyRecord)=>run.requestId===request.id);const selectedId=selectedLoadRuns.get(request.id);const run=selectedId?history.find((item:AnyRecord)=>item.id===selectedId):(loadResults.get(request.id)||history[0]);const result=run?.result;return `<div class="load-layout"><div><div class="load-card"><h3>Stress test configuration</h3><div class="field-grid" style="grid-template-columns:1fr"><div class="field"><label>Concurrent users</label><input class="input" type="number" min="1" max="200" data-load="concurrency" value="${config.concurrency}"></div><div class="field"><label>Total requests</label><input class="input" type="number" min="1" max="100000" data-load="totalRequests" value="${config.totalRequests}"></div><div class="field"><label>Delay per user (ms)</label><input class="input" type="number" min="0" max="60000" data-load="delayMs" value="${config.delayMs}"></div></div><p class="muted">Uses the current URL, body, authentication and active environment. Calls run concurrently in the Go engine.</p><button class="btn ${loadRunningId===request.id?"btn-danger":"btn-primary"}" data-action="${loadRunningId===request.id?"cancel-load":"run-load"}" style="width:100%">${loadRunningId===request.id?"■ Stop test":"▶ Run stress test"}</button></div><div class="load-card" style="margin-top:12px"><div class="load-result-head"><h3>Run history</h3><span class="spacer"></span>${history.length?`<button class="btn btn-sm btn-danger" data-action="clear-load-scenario" ${loadRunningId===request.id?"disabled":""}>⌫ Clear scenario</button>`:""}</div>${history.length?history.map((item:AnyRecord)=>`<div class="load-history-row ${run?.id===item.id?"active":""}" data-load-run="${item.id}"><span>${new Date(item.startedAt).toLocaleString()}</span><span>${item.concurrency} VUs</span><span>${item.result.total} req</span><span>${item.result.successful} OK</span><span>${Math.round(item.result.averageMs)} ms</span><span>${item.result.requestsPerSec.toFixed(1)} rps</span></div>`).join(""):'<p class="muted">No stress tests have been run for this request.</p>'}</div></div><div>${result?renderLoadResult(request.id,run,history):`<div class="load-card response-empty" style="min-height:260px"><div><strong>Ready for a stress test</strong><p>Configure the workload and run it to see latency, throughput and execution history.</p></div></div>`}</div></div>`}
function renderLoadResult(requestId:string,run:AnyRecord,history:AnyRecord[]){const result=run.result;const samples=result.samples||[];const mode=loadViewModes.get(requestId)||"table";const candidates=history.filter(item=>item.id!==run.id);let comparisonId=comparedLoadRuns.has(requestId)?comparedLoadRuns.get(requestId)!:(candidates[0]?.id||"");if(comparisonId&&!candidates.some(item=>item.id===comparisonId))comparisonId=candidates[0]?.id||"";const baseline=candidates.find(item=>item.id===comparisonId);return `<div class="load-card"><div class="load-result-head"><h3>Results · ${new Date(run.startedAt).toLocaleString()}</h3><span class="spacer"></span><button class="btn btn-sm ${mode==="table"?"btn-primary":""}" data-load-view="table" title="Execution table">▦ Table</button><button class="btn btn-sm ${mode==="chart"?"btn-primary":""}" data-load-view="chart" title="Latency graph">⌁ Graph</button></div><div class="load-metrics">${[["Completed",result.total],["Successful",result.successful],["Failed",result.failed],["Throughput",`${result.requestsPerSec.toFixed(1)} req/s`],["Average",`${result.averageMs.toFixed(1)} ms`],["P50",`${result.p50Ms} ms`],["P95",`${result.p95Ms} ms`],["P99",`${result.p99Ms} ms`],["Minimum",`${result.minMs} ms`],["Maximum",`${result.maxMs} ms`],["Total time",`${result.durationMs} ms`]].map(([label,value])=>`<div class="load-metric"><span>${label}</span><strong>${value}</strong></div>`).join("")}</div>${mode==="chart"?renderLoadChart(run,baseline,history,requestId,comparisonId):renderLoadTable(samples)}</div>`}
function renderLoadTable(samples:AnyRecord[]){return `<h3>Executions</h3><div style="overflow:auto;max-height:330px"><table class="editor-table"><thead><tr><th>#</th><th>Started</th><th>Status</th><th>Time</th><th>Size</th><th>Error</th></tr></thead><tbody>${samples.map((sample:AnyRecord)=>`<tr><td style="padding:7px">${sample.index}</td><td style="padding:7px">${new Date(sample.startedAt).toLocaleTimeString()}</td><td style="padding:7px"><strong class="status-code s${String(sample.statusCode)[0]}">${sample.statusCode||"—"}</strong></td><td style="padding:7px">${sample.durationMs} ms</td><td style="padding:7px">${formatBytes(sample.size)}</td><td style="padding:7px;color:var(--danger)">${esc(sample.error)}</td></tr>`).join("")}</tbody></table></div>`}
function renderLoadChart(run:AnyRecord,baseline:AnyRecord|undefined,history:AnyRecord[],requestId:string,comparisonId:string){const currentSamples=run.result.samples||[];const baselineSamples=baseline?.result?.samples||[];const width=900,height=330,left=52,right=18,top=18,bottom=38;const plotWidth=width-left-right,plotHeight=height-top-bottom;const maxCount=Math.max(currentSamples.length,baselineSamples.length,2);const durations=[...currentSamples,...baselineSamples].map((sample:AnyRecord)=>Number(sample.durationMs)||0);const maxDuration=Math.max(1,...durations);const x=(index:number)=>left+(Math.max(0,index-1)/(maxCount-1))*plotWidth;const y=(duration:number)=>top+plotHeight-(duration/maxDuration)*plotHeight;const path=(samples:AnyRecord[])=>samples.map((sample:AnyRecord,index:number)=>`${index?"L":"M"}${x(sample.index||index+1).toFixed(1)},${y(Number(sample.durationMs)||0).toFixed(1)}`).join(" ");const grid=Array.from({length:6},(_,index)=>{const value=Math.round(maxDuration*(5-index)/5);const py=top+plotHeight*index/5;return `<line class="chart-grid" x1="${left}" y1="${py}" x2="${width-right}" y2="${py}"/><text class="chart-axis-label" x="${left-7}" y="${py+3}" text-anchor="end">${value} ms</text>`}).join("");const xLabels=Array.from({length:5},(_,index)=>{const call=Math.max(1,Math.round(1+(maxCount-1)*index/4));const px=x(call);return `<text class="chart-axis-label" x="${px}" y="${height-12}" text-anchor="middle">#${call}</text>`}).join("");const points=(samples:AnyRecord[],css:string)=>samples.length<=120?samples.map((sample:AnyRecord,index:number)=>`<circle class="${css}" cx="${x(sample.index||index+1)}" cy="${y(Number(sample.durationMs)||0)}" r="2.5"/>`).join(""):"";return `<div class="body-toolbar"><div class="field" style="min-width:300px"><label>Compare current run with</label><select class="select" data-load-compare="${requestId}" style="width:100%"><option value="">No comparison</option>${history.filter(item=>item.id!==run.id).map(item=>`<option value="${item.id}" ${item.id===comparisonId?"selected":""}>${new Date(item.startedAt).toLocaleString()} · ${item.concurrency} VUs · ${item.result.averageMs.toFixed(1)} ms avg</option>`).join("")}</select></div></div>${baseline?renderComparison(run.result,baseline.result):""}<div class="chart-legend"><span><i class="chart-swatch current"></i>Current · ${new Date(run.startedAt).toLocaleString()}</span>${baseline?`<span><i class="chart-swatch baseline"></i>Previous · ${new Date(baseline.startedAt).toLocaleString()}</span>`:""}</div><div class="load-chart"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Load test latency by execution">${grid}${xLabels}<path class="chart-current" d="${path(currentSamples)}"/>${baseline?`<path class="chart-baseline" d="${path(baselineSamples)}"/>`:""}${points(currentSamples,"chart-point-current")}${baseline?points(baselineSamples,"chart-point-baseline"):""}<text class="chart-axis-label" x="${width/2}" y="${height-1}" text-anchor="middle">Execution order</text></svg></div>`}
function renderComparison(current:AnyRecord,baseline:AnyRecord){const cards=[comparisonMetric("Average",current.averageMs,baseline.averageMs,"ms",false),comparisonMetric("P95",current.p95Ms,baseline.p95Ms,"ms",false),comparisonMetric("P99",current.p99Ms,baseline.p99Ms,"ms",false),comparisonMetric("Throughput",current.requestsPerSec,baseline.requestsPerSec,"req/s",true)];return `<div class="comparison-grid">${cards.join("")}</div>`}
function comparisonMetric(label:string,current:number,baseline:number,unit:string,higherIsBetter:boolean){const difference=current-baseline;const percent=baseline?difference/baseline*100:0;const improved=higherIsBetter?difference>=0:difference<=0;const sign=difference>0?"+":"";return `<div class="load-metric"><span>${label} comparison</span><strong>${Number(current).toFixed(1)} ${unit}</strong><small class="${improved?"delta-good":"delta-bad"}" style="display:block;margin-top:4px">${sign}${difference.toFixed(1)} ${unit} (${sign}${percent.toFixed(1)}%)</small></div>`}

function renderKeyValueTable(list:string,items:AnyRecord[],keyLabel:string,valueLabel:string){const rows=[...items,{id:"",enabled:true,key:"",value:"",description:""}];return `<table class="editor-table"><thead><tr><th style="width:36px">On</th><th>${keyLabel}</th><th>${valueLabel}</th><th>Description</th><th style="width:62px"></th></tr></thead><tbody>${rows.map((item,index)=>`<tr><td class="check-cell"><input type="checkbox" data-list="${list}" data-index="${index}" data-field="enabled" ${item.enabled?"checked":""}></td><td><input data-list="${list}" data-index="${index}" data-field="key" value="${esc(item.key)}" placeholder="${index===items.length?"Add a new row":""}"></td><td><input data-list="${list}" data-index="${index}" data-field="value" value="${esc(item.value)}"></td><td><input data-list="${list}" data-index="${index}" data-field="description" value="${esc(item.description)}"></td><td class="row-actions">${index<items.length?`<button class="btn btn-ghost btn-sm" data-remove-row="${list}" data-index="${index}">×</button>`:""}</td></tr>`).join("")}</tbody></table>`}

function renderAuth(request:AnyRecord){const auth=request.auth||{type:"none"};const oauth=auth.type==="oauth2";return `<div class="field-grid"><div class="field wide"><label>Authentication type</label><select class="select" data-auth="type"><option value="none" ${auth.type==="none"?"selected":""}>No Auth</option><option value="basic" ${auth.type==="basic"?"selected":""}>Basic Auth</option><option value="bearer" ${auth.type==="bearer"?"selected":""}>Bearer Token</option><option value="apikey" ${auth.type==="apikey"?"selected":""}>API Key</option><option value="oauth2" ${oauth?"selected":""}>OAuth 2.0</option></select></div>${auth.type==="basic"?`<div class="field"><label>Username</label><input class="input" data-auth="username" value="${esc(auth.username)}"></div><div class="field"><label>Password</label><input class="input" type="password" data-auth="password" value="${esc(auth.password)}"></div>`:""}${auth.type==="bearer"?`<div class="field wide"><label>Token</label><input class="input" type="password" data-auth="token" value="${esc(auth.token)}" placeholder="{{token}}"></div>`:""}${auth.type==="apikey"?`<div class="field"><label>Key</label><input class="input" data-auth="key" value="${esc(auth.key)}"></div><div class="field"><label>Value</label><input class="input" type="password" data-auth="value" value="${esc(auth.value)}"></div><div class="field"><label>Add to</label><select class="select" data-auth="addTo"><option value="header" ${auth.addTo!=="query"?"selected":""}>Header</option><option value="query" ${auth.addTo==="query"?"selected":""}>Query parameter</option></select></div>`:""}${oauth?`<div class="field"><label>Grant type</label><select class="select" data-auth="oauthFlow"><option value="client_credentials" ${!auth.oauthFlow||auth.oauthFlow==="client_credentials"?"selected":""}>Client Credentials</option><option value="password" ${auth.oauthFlow==="password"?"selected":""}>Password</option><option value="refresh_token" ${auth.oauthFlow==="refresh_token"?"selected":""}>Refresh Token</option></select></div><div class="field"><label>Client authentication</label><select class="select" data-auth="clientAuth"><option value="body" ${auth.clientAuth!=="basic"?"selected":""}>Credentials in body</option><option value="basic" ${auth.clientAuth==="basic"?"selected":""}>Basic Auth header</option></select></div><div class="field wide"><label>Token URL</label><input class="input" data-auth="tokenUrl" value="${esc(auth.tokenUrl)}" placeholder="https://identity.example.com/oauth/token"></div><div class="field"><label>Client ID</label><input class="input" data-auth="clientId" value="${esc(auth.clientId)}"></div><div class="field"><label>Client Secret</label><input class="input" type="password" data-auth="clientSecret" value="${esc(auth.clientSecret)}"></div><div class="field wide"><label>Scope</label><input class="input" data-auth="scope" value="${esc(auth.scope)}" placeholder="read write"></div>${auth.oauthFlow==="password"?`<div class="field"><label>Username</label><input class="input" data-auth="oauthUsername" value="${esc(auth.oauthUsername)}"></div><div class="field"><label>Password</label><input class="input" type="password" data-auth="oauthPassword" value="${esc(auth.oauthPassword)}"></div>`:""}${auth.oauthFlow==="refresh_token"?`<div class="field wide"><label>Refresh Token</label><input class="input" type="password" data-auth="refreshToken" value="${esc(auth.refreshToken)}"></div>`:""}<div class="field wide oauth-status-row"><button class="btn btn-primary" data-action="oauth-token">Get New Access Token</button><span class="badge oauth-auto">↻ Automatic on Send</span>${auth.accessToken?`<span class="badge">Token ready${auth.expiresAt?` · expires ${esc(new Date(auth.expiresAt).toLocaleString())}`:""}</span>`:`<span class="badge warn">No token · it will be requested automatically</span>`}</div><div class="field wide"><label>Access Token</label><input class="input" type="password" data-auth="accessToken" value="${esc(auth.accessToken)}" placeholder="Automatically obtained when you send the request"></div>`:""}</div>`}

function renderBody(request:AnyRecord){if(request.protocol==="SOAP")return `<div class="body-toolbar"><span class="badge">XML</span><button class="btn btn-sm" data-action="format-body">Format XML</button></div><textarea class="code-editor" data-bind="body" spellcheck="false">${esc(request.body)}</textarea>`;const types=["none","json","xml","text","html","form","multipart","binary"];return `<div class="body-toolbar"><select class="select" data-bind="bodyType">${types.map(t=>`<option value="${t}" ${t===request.bodyType?"selected":""}>${t==="none"?"None":t==="form"?"x-www-form-urlencoded":t}</option>`).join("")}</select>${["json","xml"].includes(request.bodyType)?'<button class="btn btn-sm" data-action="format-body">Format</button><button class="btn btn-sm" data-action="minify-body">Minify</button>':""}</div>${request.bodyType==="none"?'<div class="response-empty">This request has no body.</div>':request.bodyType==="multipart"?renderMultipart(request.multipart||[]):request.bodyType==="form"?renderKeyValueTable("params",request.params||[],"Key","Value"):`<textarea class="code-editor" data-bind="body" spellcheck="false" placeholder="Request body">${esc(request.body)}</textarea>`}`}
function renderMultipart(items:AnyRecord[]){const rows=[...items,{id:"",enabled:true,type:"TEXT",key:"",value:""}];return `<table class="editor-table"><thead><tr><th>On</th><th>Type</th><th>Key</th><th>Value / file path</th><th></th></tr></thead><tbody>${rows.map((p,i)=>`<tr><td class="check-cell"><input type="checkbox" data-list="multipart" data-index="${i}" data-field="enabled" ${p.enabled?"checked":""}></td><td><select data-list="multipart" data-index="${i}" data-field="type"><option ${p.type==="TEXT"?"selected":""}>TEXT</option><option ${p.type==="FILE"?"selected":""}>FILE</option></select></td><td><input data-list="multipart" data-index="${i}" data-field="key" value="${esc(p.key)}"></td><td><input data-list="multipart" data-index="${i}" data-field="value" value="${esc(p.value)}"></td><td class="row-actions">${p.type==="FILE"?`<button class="btn btn-ghost btn-sm" data-pick-file="${i}">…</button>`:""}${i<items.length?`<button class="btn btn-ghost btn-sm" data-remove-row="multipart" data-index="${i}">×</button>`:""}</td></tr>`).join("")}</tbody></table>`}

function renderResponse(request:AnyRecord){const response=responses.get(request.id);if(!response)return `<div class="response-empty"><div><div style="font-size:25px;margin-bottom:8px">↯</div><strong>Ready to send</strong><p>Response details will appear here.</p></div></div>`;return `<div class="response-head"><div class="metric"><span>Status</span><strong class="status-code s${String(response.statusCode)[0]}">${esc(response.status)}</strong></div><div class="metric"><span>Time</span><strong>${response.durationMs} ms</strong></div><div class="metric"><span>Size</span><strong>${formatBytes(response.size)}</strong></div>${response.truncated?'<span class="badge warn">Preview truncated</span>':''}<span class="spacer"></span>${!response.binary?'<button class="btn btn-sm" data-action="copy-response">Copy response</button>':''}<button class="btn btn-sm" data-action="save-response">Save response</button></div><div class="subtabs">${responseTabs(response).map(([id,label])=>`<button data-response-tab="${id}" class="${responseTab===id?"active":""}">${label}</button>`).join("")}</div><div class="pane-body">${renderResponsePane(response)}</div>`}
function responseTabs(response:AnyRecord):[string,string][]{const tabs:[string,string][]=[["pretty","Pretty"],["raw","Raw"],["headers","Headers"],["cookies","Cookies"],["timing","Timing"]];if((response.contentType||"").includes("text/html"))tabs.splice(2,0,["preview","Preview"]);return tabs}
function renderResponsePane(response:AnyRecord){
  if(responseTab==="headers")return renderHeaderResponse(response.headers);
  if(responseTab==="cookies")return response.cookies?.length?`<pre class="pretty">${esc(response.cookies.join("\n"))}</pre>`:`<div class="response-empty">No cookies were returned.</div>`;
  if(responseTab==="timing")return `<table class="editor-table"><tbody>${[["DNS",response.timings?.dns],["Connect",response.timings?.connect],["TLS",response.timings?.tls],["TTFB",response.timings?.ttfb],["Download",response.timings?.download],["Total",response.timings?.total]].map(([k,v])=>`<tr><td style="padding:9px 12px">${k}</td><td style="padding:9px 12px"><strong>${v||0} ms</strong></td></tr>`).join("")}</tbody></table>${response.redirects?.length?`<p class="muted">Redirect chain</p>${response.redirects.map((r:AnyRecord)=>`<div class="badge">${r.statusCode} → ${esc(r.url)}</div>`).join(" ")}`:""}`;
  if(responseTab==="preview")return `<iframe sandbox="" style="width:100%;height:100%;min-height:240px;border:1px solid var(--line);background:white;border-radius:8px" srcdoc="${esc(response.body)}"></iframe>`;
  if(response.binary){if((response.contentType||"").startsWith("image/"))return `<img alt="Response preview" style="max-width:100%;max-height:100%;border-radius:8px" src="data:${esc(response.contentType)};base64,${response.bodyBase64}">`;return `<div class="response-empty"><div><strong>Binary Response</strong><p>${esc(response.contentType||"application/octet-stream")} · ${formatBytes(response.size)}</p><button class="btn" data-action="save-response">Save response</button></div></div>`}
  const body=response.body||"";if(responseTab==="raw")return `<pre class="pretty">${esc(body)}</pre>`;
  let formatted=body;const type=(response.contentType||"").toLowerCase();try{if(type.includes("json")||body.trim().startsWith("{")||body.trim().startsWith("["))formatted=JSON.stringify(JSON.parse(body),null,2);else if(type.includes("xml")||body.trim().startsWith("<"))formatted=formatXml(body)}catch{}
  return `${response.soapFault?`<div class="soap-fault"><strong>SOAP Fault</strong><span>Code: ${esc(response.soapFault.code)}<br>Message: ${esc(response.soapFault.message)}</span></div>`:""}<pre class="pretty">${highlight(formatted,type)}</pre>`;
}
function renderHeaderResponse(headers:AnyRecord){const entries=Object.entries(headers||{});return entries.length?`<table class="editor-table"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody>${entries.map(([key,value])=>`<tr><td style="padding:8px"><strong>${esc(key)}</strong></td><td style="padding:8px">${esc((value as string[]).join(", "))}</td></tr>`).join("")}</tbody></table>`:`<div class="response-empty">No headers.</div>`}
function formatBytes(bytes:number){if(!Number.isFinite(bytes)||bytes<0)return "—";if(bytes<1024)return `${bytes} B`;if(bytes<1048576)return `${(bytes/1024).toFixed(1)} KB`;return `${(bytes/1048576).toFixed(1)} MB`}
function responseCopyText(response:AnyRecord){const body=response.body||"";if(responseTab==="raw")return body;const type=(response.contentType||"").toLowerCase();try{if(type.includes("json")||body.trim().startsWith("{")||body.trim().startsWith("["))return JSON.stringify(JSON.parse(body),null,2);if(type.includes("xml")||body.trim().startsWith("<"))return formatXml(body)}catch{}return body}
async function copyResponse(){const response=responses.get(activeId);if(!response||response.binary)return;try{await navigator.clipboard.writeText(responseCopyText(response));toast(responseTab==="raw"?"Raw response copied":"Response copied") }catch(e){toast(`Could not copy response: ${e}`,true)}}
function highlight(body:string,type:string){let safe=esc(body);if(type.includes("xml")||body.trim().startsWith("<"))return safe.replace(/(&lt;\/?)([\w:.-]+)/g,'$1<span class="tag">$2</span>').replace(/([\w:.-]+)(=)(&quot;.*?&quot;)/g,'<span class="attr">$1</span>$2<span class="string">$3</span>');return safe.replace(/(&quot;.*?&quot;)(\s*:)?|\b(true|false|null)\b|(-?\d+(?:\.\d+)?)/g,(match,key,colon,bool,num)=>key?`<span class="${colon?"key":"string"}">${key}</span>${colon||""}`:bool?`<span class="${bool==="null"?"null":"boolean"}">${bool}</span>`:`<span class="number">${num}</span>`)}
function formatXml(xml:string){const parser=new DOMParser();const doc=parser.parseFromString(xml,"application/xml");if(doc.querySelector("parsererror"))throw new Error(doc.querySelector("parsererror")?.textContent||"Invalid XML");const serialized=new XMLSerializer().serializeToString(doc).replace(/>\s*</g,"><");let out="",pad=0;for(const token of serialized.replace(/</g,"\n<").trim().split("\n")){if(/^<\//.test(token))pad--;out+=`${"  ".repeat(Math.max(0,pad))}${token}\n`;if(/^<[^!?/][^>]*[^/]?>$/.test(token)&&!token.includes("</"))pad++}return out.trim()}

function urlWithParams(request:AnyRecord){try{const url=new URL(request.url);for(const p of request.params||[]){if(p.enabled&&p.key)url.searchParams.append(p.key,p.value||"")}return url.toString()}catch{return request.url||""}}
function parseURLInput(value:string,request:AnyRecord){try{const parsed=new URL(value);request.params=[];parsed.searchParams.forEach((v,k)=>request.params.push({id:uid(),enabled:true,key:k,value:v,description:""}));parsed.search="";request.url=parsed.toString()}catch{request.url=value}}

async function createRequest(protocol:string,collectionId="",folderId=""){activeFlowId="";try{let request=await api("NewRequest",activeWorkspace(),protocol);request.collectionId=collectionId;request.folderId=folderId;if(collectionId){request=await api("SaveRequest",request);state.requests.push(structuredClone(request));drafts.set(request.id,{data:request,dirty:false})}else{drafts.set(request.id,{data:request,dirty:true})}tabs.push(request.id);activeId=request.id;requestTab=protocol==="SOAP"?"soap":"params";await api("SaveTabs",tabs.filter(id=>state.requests.some((r:AnyRecord)=>r.id===id)));renderTabs();renderSidebar();renderWorkspace()}catch(e){toast(String(e),true)}}
function openRequest(id:string){activeFlowId="";if(!drafts.has(id)){const request=state.requests.find((r:AnyRecord)=>r.id===id);if(request)drafts.set(id,{data:structuredClone(request),dirty:false})}if(!tabs.includes(id))tabs.push(id);activeId=id;void api("SaveTabs",tabs.filter(tab=>state.requests.some((r:AnyRecord)=>r.id===tab)));renderTabs();renderSidebar();renderWorkspace()}
async function persistDraft(id:string){const draft=drafts.get(id);if(!draft)return null;if(id===activeId)syncVisibleFields();const saved=await api("SaveRequest",draft.data);draft.data=saved;draft.dirty=false;const index=state.requests.findIndex((request:AnyRecord)=>request.id===saved.id);if(index>=0)state.requests[index]=structuredClone(saved);else state.requests.push(structuredClone(saved));return saved}
async function saveCurrent(){if(!drafts.get(activeId))return;try{await persistDraft(activeId);await api("SaveTabs",tabs);renderTabs();renderSidebar();toast("Request saved") }catch(e){toast(String(e),true)}}
async function duplicateCurrent(){const request=activeRequest();if(!request)return;syncVisibleFields();return duplicateRequest(request)}
async function duplicateRequest(request:AnyRecord){try{const duplicated=await api("DuplicateRequest",request);state.requests.push(structuredClone(duplicated));drafts.set(duplicated.id,{data:duplicated,dirty:false});tabs.push(duplicated.id);activeId=duplicated.id;await api("SaveTabs",tabs);renderTabs();renderSidebar();renderWorkspace();toast("Request duplicated") }catch(e){toast(String(e),true)}}
function oauthTokenNeedsRenewal(request:AnyRecord){const auth=request?.auth;if(auth?.type!=="oauth2")return false;if(!String(auth.accessToken||"").trim())return true;if(!String(auth.expiresAt||"").trim())return false;const expiresAt=new Date(auth.expiresAt).getTime();return !Number.isFinite(expiresAt)||expiresAt<=Date.now()+30000}
async function ensureOAuthToken(request:AnyRecord,force=false){if(request?.auth?.type!=="oauth2"||(!force&&!oauthTokenNeedsRenewal(request)))return false;const collection=state.collections.find((item:AnyRecord)=>item.id===request.collectionId);const result=await api("GetOAuthToken",{auth:request.auth,environmentId:state.settings.activeEnvironmentId||"",globalVariables:{},collectionVariables:collection?.variables||{},requestVariables:request.variables||{}});request.auth.accessToken=result.accessToken;if(result.refreshToken)request.auth.refreshToken=result.refreshToken;request.auth.expiresAt=result.expiresAt;const draft=drafts.get(request.id);if(draft)draft.dirty=true;renderTabs();toast(force?"OAuth 2.0 access token obtained":"OAuth 2.0 token renewed automatically");return true}
async function acquireOAuthToken(){const request=activeRequest();if(!request)return;try{await ensureOAuthToken(request,true);renderWorkspace()}catch(e){toast(String(e),true)}}
async function runLoadTest(){const request=activeRequest();if(!request||loadRunningId)return;try{await ensureOAuthToken(request)}catch(e){toast(`Could not obtain OAuth 2.0 token: ${e}`,true);return}const config=loadConfigs.get(request.id)||{concurrency:5,totalRequests:50,delayMs:0};const collection=state.collections.find((c:AnyRecord)=>c.id===request.collectionId);const executionId=uid();request.__loadExecutionId=executionId;loadRunningId=request.id;renderWorkspace();try{const run=await api("RunLoadTest",{executionId,request,environmentId:state.settings.activeEnvironmentId||"",globalVariables:{},collectionVariables:collection?.variables||{},concurrency:config.concurrency,totalRequests:config.totalRequests,delayMs:config.delayMs});state.loadTests=[run,...(state.loadTests||[])];loadResults.set(request.id,run);selectedLoadRuns.delete(request.id);toast(`Stress test finished: ${run.result.successful} successful, ${run.result.failed} failed`)}catch(e){toast(String(e),true)}finally{loadRunningId="";renderWorkspace()}}
async function cancelLoadTest(){const request=activeRequest();if(request?.__loadExecutionId){await api("CancelLoadTest",request.__loadExecutionId);toast("Stopping stress test…")}}
function clearLoadScenario(){const request=activeRequest();if(!request||loadRunningId===request.id)return;const count=(state.loadTests||[]).filter((run:AnyRecord)=>run.requestId===request.id).length;showModal("Clear Load Test scenario",`<p>This will permanently remove <strong>${count}</strong> saved run${count===1?"":"s"}, results, graphs and comparisons for <strong>${esc(request.name)}</strong>.</p><p class="muted">The request, authentication and environment will not be changed. Test configuration returns to 5 users and 50 requests.</p>`,[{label:"Cancel",action:closeModal},{label:"Clear scenario",danger:true,action:async()=>{try{await api("ClearLoadTests",request.id);state.loadTests=(state.loadTests||[]).filter((run:AnyRecord)=>run.requestId!==request.id);loadResults.delete(request.id);selectedLoadRuns.delete(request.id);comparedLoadRuns.delete(request.id);loadViewModes.delete(request.id);loadConfigs.delete(request.id);closeModal();renderWorkspace();toast("Load Test scenario cleared") }catch(e){toast(String(e),true)}}}])}
async function closeTab(id:string){return closeTabs(tabs.filter(tab=>tab===id))}
async function closeTabs(ids:string[]){const targets=ids.filter(id=>tabs.includes(id));if(!targets.length)return;if(targets.includes(activeId))syncVisibleFields();const dirty=targets.filter(id=>drafts.get(id)?.dirty);if(dirty.length){showModal("Unsaved changes",`<p>${dirty.length===1?"This request has":"These requests have"} unsaved changes.</p><p class="muted">Save before closing ${targets.length===1?"the tab":`${targets.length} tabs`}?</p>`,[{label:"Cancel",action:closeModal},{label:"Discard all",action:()=>void finishCloseTabs(targets,false)},{label:"Save all",primary:true,action:()=>void finishCloseTabs(targets,true)}]);return}await finishCloseTabs(targets,false)}
async function finishCloseTabs(ids:string[],saveDirty:boolean){try{if(saveDirty){for(const id of ids){if(drafts.get(id)?.dirty)await persistDraft(id)}}const oldTabs=[...tabs];const oldActiveIndex=oldTabs.indexOf(activeId);tabs=tabs.filter(id=>!ids.includes(id));if(ids.includes(activeId))activeId=tabs[Math.min(Math.max(oldActiveIndex,0),tabs.length-1)]||"";for(const id of ids){const saved=state.requests.find((request:AnyRecord)=>request.id===id);if(saved)drafts.set(id,{data:structuredClone(saved),dirty:false});else drafts.delete(id);responses.delete(id)}await api("SaveTabs",tabs.filter(tab=>state.requests.some((request:AnyRecord)=>request.id===tab)));closeModal();closeContextMenu();renderTabs();renderSidebar();renderWorkspace()}catch(e){toast(`Could not close tabs: ${e}`,true)}}

async function sendCurrent(){const draft=drafts.get(activeId);if(!draft||sendingId)return;syncVisibleFields();const request=draft.data;if(!request.url.trim()){toast("Enter a request URL",true);return}try{await ensureOAuthToken(request)}catch(e){toast(`Could not obtain OAuth 2.0 token: ${e}`,true);return}sendingId=activeId;renderWorkspace();const executionId=uid();request.__executionId=executionId;try{const collection=state.collections.find((c:AnyRecord)=>c.id===request.collectionId);const result=await api("ExecuteRequest",{executionId,request,environmentId:state.settings.activeEnvironmentId||"",globalVariables:{},collectionVariables:collection?.variables||{}});responses.set(activeId,result);state.history=[{id:uid(),workspaceId:request.workspaceId,executedAt:new Date().toISOString(),method:request.method,url:result.resolvedUrl,name:request.name,statusCode:result.statusCode,durationMs:result.durationMs,size:result.size,request:structuredClone(request),response:result},...(state.history||[])];responseTab="pretty"}catch(e){toast(String(e),true)}finally{sendingId="";renderSidebar();renderWorkspace()}}
async function cancelCurrent(){const request=activeRequest();if(request?.__executionId){await api("CancelRequest",request.__executionId);toast("Cancelling request…")}}

function syncVisibleFields(){const request=activeRequest();if(!request)return;document.querySelectorAll<HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement>("[data-bind]").forEach(el=>{const key=el.dataset.bind!;request[key]=el.value});const url=document.querySelector<HTMLInputElement>("#url-input");if(url)parseURLInput(url.value,request)}

function showModal(title:string,body:string,buttons:{label:string;primary?:boolean;danger?:boolean;action:()=>void|Promise<void>}[],wide=false){closeModal();const overlay=document.createElement("div");overlay.className="overlay";overlay.id="modal-overlay";overlay.innerHTML=`<div class="modal ${wide?"wide":""}"><div class="modal-head"><h2>${esc(title)}</h2><button class="btn btn-ghost btn-sm" data-modal-close>×</button></div><div class="modal-body">${body}</div><div class="modal-foot" id="modal-buttons"></div></div>`;document.body.append(overlay);const foot=overlay.querySelector("#modal-buttons")!;buttons.forEach(item=>{const button=document.createElement("button");button.className=`btn ${item.primary?"btn-primary":""} ${item.danger?"btn-danger":""}`;button.textContent=item.label;button.onclick=()=>void item.action();foot.append(button)});overlay.querySelector("[data-modal-close]")?.addEventListener("click",closeModal)}
function closeModal(){document.querySelector("#modal-overlay")?.remove()}

function installSplitter(){const splitter=document.querySelector<HTMLElement>("#splitter");const split=document.querySelector<HTMLElement>(".split");if(!splitter||!split)return;splitter.onpointerdown=e=>{if((e.target as HTMLElement).closest("button")||state.settings.responsePaneCollapsed)return;splitter.setPointerCapture(e.pointerId);splitter.onpointermove=move=>{const rect=split.getBoundingClientRect();const value=Math.min(80,Math.max(20,((move.clientY-rect.top)/rect.height)*100));document.documentElement.style.setProperty("--split",`${value}%`);state.settings.editorSplitPercent=Math.round(value)};splitter.onpointerup=()=>{splitter.onpointermove=null;void api("SaveSettings",state.settings)}}}
function toggleResponsePane(){state.settings.responsePaneCollapsed=!state.settings.responsePaneCollapsed;void api("SaveSettings",state.settings);renderWorkspace()}

async function createNamed(kind:"workspace"|"collection"|"folder",parentId=""){
  const labels={workspace:"workspace",collection:"collection",folder:"folder"};showModal(`New ${labels[kind]}`,`<div class="field"><label>Name</label><input class="input" id="entity-name" style="width:100%" autofocus></div>`,[{label:"Cancel",action:closeModal},{label:"Create",primary:true,action:async()=>{const name=(document.querySelector<HTMLInputElement>("#entity-name")?.value||"").trim();if(!name)return;try{if(kind==="workspace"){const item=await api("SaveWorkspace",{id:"",name,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});state.workspaces.push(item);state.settings.activeWorkspaceId=item.id;await api("SaveSettings",state.settings)}else if(kind==="collection"){const item=await api("SaveCollection",{id:"",workspaceId:activeWorkspace(),name,description:"",variables:{},sortOrder:state.collections.length});state.collections.push(item)}else{const item=await api("SaveFolder",{id:"",collectionId:parentId,parentId:"",name,sortOrder:state.folders.length});state.folders.push(item)}closeModal();renderShell()}catch(e){toast(String(e),true)}}}])
}

function closeContextMenu(){document.querySelector("#tree-context-menu")?.remove();document.querySelector("#tab-context-menu")?.remove()}
function showTabMenu(id:string,x:number,y:number){closeContextMenu();const index=tabs.indexOf(id);if(index<0)return;const menu=document.createElement("div");menu.id="tab-context-menu";menu.className="context-menu";menu.innerHTML=`<button data-tab-context-action="close" data-id="${id}"><span>×</span><span>Close</span></button><button data-tab-context-action="close-others" data-id="${id}" ${tabs.length<2?"disabled":""}><span>◫</span><span>Close others</span></button><button data-tab-context-action="close-right" data-id="${id}" ${index===tabs.length-1?"disabled":""}><span>⇥</span><span>Close tabs to the right</span></button><div class="separator"></div><button class="danger" data-tab-context-action="close-all" data-id="${id}"><span>×</span><span>Close all tabs</span></button>`;document.body.append(menu);const rect=menu.getBoundingClientRect();menu.style.left=`${Math.max(6,Math.min(x,window.innerWidth-rect.width-6))}px`;menu.style.top=`${Math.max(6,Math.min(y,window.innerHeight-rect.height-6))}px`}
function handleTabContextAction(action:string,id:string){closeContextMenu();const index=tabs.indexOf(id);if(index<0)return;if(action==="close")return void closeTabs([id]);if(action==="close-others")return void closeTabs(tabs.filter(tab=>tab!==id));if(action==="close-right")return void closeTabs(tabs.slice(index+1));if(action==="close-all")return void closeTabs([...tabs])}
function showTreeMenu(kind:string,id:string,x:number,y:number){closeContextMenu();const items=kind==="collection"?[["new-rest","GET","New REST request"],["new-soap","SOAP","New SOAP request"],["new-folder","▰","New folder"],["separator","",""] ,["rename","✎","Rename"],["delete","×","Delete"]]:kind==="folder"?[["new-rest","GET","New REST request"],["new-soap","SOAP","New SOAP request"],["separator","",""] ,["rename","✎","Rename"],["delete","×","Delete"]]:[["duplicate","⧉","Duplicate request"],["rename","✎","Rename"],["separator","",""] ,["delete","×","Delete request"]];const menu=document.createElement("div");menu.id="tree-context-menu";menu.className="context-menu";menu.innerHTML=items.map(([action,icon,label])=>action==="separator"?'<div class="separator"></div>':`<button class="${action==="delete"?"danger":""}" data-context-action="${action}" data-kind="${kind}" data-id="${id}"><span>${icon}</span><span>${label}</span></button>`).join("");document.body.append(menu);const rect=menu.getBoundingClientRect();menu.style.left=`${Math.max(6,Math.min(x,window.innerWidth-rect.width-6))}px`;menu.style.top=`${Math.max(6,Math.min(y,window.innerHeight-rect.height-6))}px`}
function collectionForTreeItem(kind:string,id:string){if(kind==="collection")return id;if(kind==="folder")return state.folders.find((f:AnyRecord)=>f.id===id)?.collectionId||"";return state.requests.find((r:AnyRecord)=>r.id===id)?.collectionId||""}
async function handleContextAction(action:string,kind:string,id:string){closeContextMenu();const collectionId=collectionForTreeItem(kind,id);const folderId=kind==="folder"?id:"";if(action==="new-rest")return createRequest("REST",collectionId,folderId);if(action==="new-soap")return createRequest("SOAP",collectionId,folderId);if(action==="new-folder")return createNamed("folder",id);if(action==="rename")return showRenameEntity(kind,id);if(action==="delete")return showDeleteEntity(kind,id);if(action==="duplicate"){const request=drafts.get(id)?.data||state.requests.find((r:AnyRecord)=>r.id===id);if(request)return duplicateRequest(request)}}
function showRenameEntity(kind:string,id:string){const source=kind==="collection"?state.collections.find((x:AnyRecord)=>x.id===id):kind==="folder"?state.folders.find((x:AnyRecord)=>x.id===id):(drafts.get(id)?.data||state.requests.find((x:AnyRecord)=>x.id===id));if(!source)return;showModal(`Rename ${kind}`,`<div class="field"><label>Name</label><input class="input" id="rename-value" style="width:100%" value="${esc(source.name)}" autofocus></div>`,[{label:"Cancel",action:closeModal},{label:"Rename",primary:true,action:async()=>{const name=(document.querySelector<HTMLInputElement>("#rename-value")?.value||"").trim();if(!name)return;try{if(kind==="collection"){source.name=name;await api("SaveCollection",source)}else if(kind==="folder"){source.name=name;await api("SaveFolder",source)}else{const savedSource=state.requests.find((r:AnyRecord)=>r.id===id);const updated={...(savedSource||source),name};const saved=await api("SaveRequest",updated);const index=state.requests.findIndex((r:AnyRecord)=>r.id===id);if(index>=0)state.requests[index]=structuredClone(saved);const draft=drafts.get(id);if(draft)draft.data.name=name}closeModal();renderTabs();renderSidebar();renderWorkspace();toast("Renamed") }catch(e){toast(String(e),true)}}}])}
function showDeleteEntity(kind:string,id:string){const source=kind==="collection"?state.collections.find((x:AnyRecord)=>x.id===id):kind==="folder"?state.folders.find((x:AnyRecord)=>x.id===id):state.requests.find((x:AnyRecord)=>x.id===id);if(!source)return;const requestCount=kind==="collection"?state.requests.filter((r:AnyRecord)=>r.collectionId===id).length:kind==="folder"?state.requests.filter((r:AnyRecord)=>r.folderId===id).length:0;const detail=kind==="collection"?`This also deletes ${requestCount} request${requestCount===1?"":"s"} and all folders in the collection.`:kind==="folder"?`${requestCount} request${requestCount===1?"":"s"} will be moved to the collection root.`:"This request and its open tab will be removed.";showModal(`Delete ${source.name}?`,`<p>${esc(detail)}</p><p class="muted">This action cannot be undone.</p>`,[{label:"Cancel",action:closeModal},{label:"Delete",danger:true,action:async()=>{try{await api("DeleteEntity",kind,id);if(kind==="collection"){const removed=state.requests.filter((r:AnyRecord)=>r.collectionId===id).map((r:AnyRecord)=>r.id);state.collections=state.collections.filter((c:AnyRecord)=>c.id!==id);state.folders=state.folders.filter((f:AnyRecord)=>f.collectionId!==id);state.requests=state.requests.filter((r:AnyRecord)=>r.collectionId!==id);removeRequestUI(removed)}else if(kind==="folder"){state.folders=state.folders.filter((f:AnyRecord)=>f.id!==id);for(const request of state.requests.filter((r:AnyRecord)=>r.folderId===id)){request.folderId="";const draft=drafts.get(request.id);if(draft)draft.data.folderId=""}}else{state.requests=state.requests.filter((r:AnyRecord)=>r.id!==id);removeRequestUI([id])}await api("SaveTabs",tabs);closeModal();renderTabs();renderSidebar();renderWorkspace();toast("Deleted") }catch(e){toast(String(e),true)}}}])}
function removeRequestUI(ids:string[]){for(const id of ids){tabs=tabs.filter(tab=>tab!==id);drafts.delete(id);responses.delete(id)}if(ids.includes(activeId))activeId=tabs.at(-1)||""}
async function moveRequest(requestId:string,collectionId:string,folderId:string){const index=state.requests.findIndex((r:AnyRecord)=>r.id===requestId);if(index<0)return;const updated=structuredClone(state.requests[index]);if(updated.collectionId===collectionId&&updated.folderId===folderId)return;updated.collectionId=collectionId;updated.folderId=folderId;try{const saved=await api("SaveRequest",updated);state.requests[index]=structuredClone(saved);const draft=drafts.get(requestId);if(draft){draft.data.collectionId=collectionId;draft.data.folderId=folderId;if(!draft.dirty)draft.data=structuredClone(saved)}renderSidebar();if(activeId===requestId)renderWorkspace();toast(folderId?"Request moved to folder":"Request moved to collection root")}catch(e){toast(String(e),true)}}
function toggleTree(kind:string,id:string){const key=`${kind}:${id}`;if(collapsedTree.has(key))collapsedTree.delete(key);else collapsedTree.add(key);state.settings.collapsedTreeIds=[...collapsedTree];void api("SaveSettings",state.settings);renderSidebar()}
async function moveFolder(folderId:string,collectionId:string,targetFolderId=""){const folder=state.folders.find((f:AnyRecord)=>f.id===folderId);if(!folder||folderId===targetFolderId)return;const target=targetFolderId?state.folders.find((f:AnyRecord)=>f.id===targetFolderId):null;const siblings=state.folders.filter((f:AnyRecord)=>f.collectionId===collectionId&&f.id!==folderId);const sortOrder=target?.sortOrder??(siblings.reduce((max:number,item:AnyRecord)=>Math.max(max,item.sortOrder||0),-1)+1);try{await api("MoveFolder",{folderId,collectionId,sortOrder});folder.collectionId=collectionId;folder.sortOrder=sortOrder;for(const request of state.requests.filter((r:AnyRecord)=>r.folderId===folderId)){request.collectionId=collectionId;const draft=drafts.get(request.id);if(draft)draft.data.collectionId=collectionId}state.folders.sort((a:AnyRecord,b:AnyRecord)=>(a.sortOrder||0)-(b.sortOrder||0)||a.name.localeCompare(b.name));renderSidebar();if(activeRequest()?.folderId===folderId)renderWorkspace();toast("Folder moved with all requests")}catch(e){toast(String(e),true)}}

function showImportCurl(){showModal("Import cURL",`<p class="muted">Paste a cURL command. Headers, body, multipart fields and supported authentication are converted locally.</p><textarea class="code-editor" id="curl-input" style="height:220px" placeholder="curl --location 'https://api.example.com/users'"></textarea>`,[{label:"Cancel",action:closeModal},{label:"Import",primary:true,action:async()=>{try{const command=document.querySelector<HTMLTextAreaElement>("#curl-input")?.value||"";const request=await api("ImportCurl",command,activeWorkspace());drafts.set(request.id,{data:request,dirty:true});tabs.push(request.id);activeId=request.id;closeModal();renderTabs();renderWorkspace()}catch(e){toast(String(e),true)}}}],true)}
function showImportWSDL(){showModal("Import WSDL",`<div class="field-grid"><div class="field wide"><label>Source</label><input class="input" id="wsdl-source" placeholder="https://server/service?wsdl or C:\\service.wsdl"></div><div class="field wide"><label><input type="checkbox" id="wsdl-url" checked> Source is a URL</label></div></div><p class="muted">The importer reads services, endpoints, operations and SOAPAction, then creates a collection of editable SOAP requests.</p>`,[{label:"Cancel",action:closeModal},{label:"Import",primary:true,action:async()=>{try{const source=document.querySelector<HTMLInputElement>("#wsdl-source")?.value||"";const fromUrl=document.querySelector<HTMLInputElement>("#wsdl-url")?.checked||false;const result=await api("ImportWSDL",{workspaceId:activeWorkspace(),source,fromUrl});const collection=await api("SaveCollection",{id:"",workspaceId:activeWorkspace(),name:result.name,description:`WSDL imported from ${source}`,variables:{},sortOrder:state.collections.length});state.collections.push(collection);for(const operation of result.operations){const request=await api("NewRequest",activeWorkspace(),"SOAP");Object.assign(request,{collectionId:collection.id,name:operation.name,url:result.endpoint,soapAction:operation.soapAction,body:operation.envelope,wsdlService:result.name,wsdlOperation:operation.name});const saved=await api("SaveRequest",request);state.requests.push(saved);drafts.set(saved.id,{data:structuredClone(saved),dirty:false})}closeModal();renderSidebar();toast(`${result.operations.length} SOAP operations imported`)}catch(e){toast(String(e),true)}}}],true)}

function showEnvironmentManager(){const envs=environmentsForWorkspace();const current=envs.find((e:AnyRecord)=>e.id===state.settings.activeEnvironmentId)||envs[0];const renderVariables=(env:AnyRecord|null|undefined)=>`<input type="hidden" id="env-id" value="${esc(env?.id)}"><div class="field"><label>Environment name</label><input class="input" id="env-name" value="${esc(env?.name||"New environment")}" style="width:100%"></div><br><table class="editor-table" id="env-vars"><thead><tr><th>On</th><th>Variable</th><th>Initial value</th><th>Current value</th><th>Secret</th></tr></thead><tbody>${[...(env?.variables||[]),{id:"",enabled:true,key:"",initialValue:"",currentValue:"",secret:false}].map((v:AnyRecord)=>`<tr data-env-row><td class="check-cell"><input type="checkbox" data-v="enabled" ${v.enabled?"checked":""}></td><td><input data-v="key" value="${esc(v.key)}"></td><td><input data-v="initialValue" type="${v.secret?"password":"text"}" value="${esc(v.initialValue)}"></td><td><input data-v="currentValue" type="${v.secret?"password":"text"}" value="${esc(v.currentValue)}"></td><td class="check-cell"><input type="checkbox" data-v="secret" ${v.secret?"checked":""}></td></tr>`).join("")}</tbody></table>`;showModal("Environments",`${envs.length?`<div class="body-toolbar"><select class="select" id="env-modal-select">${envs.map((e:AnyRecord)=>`<option value="${e.id}" ${e.id===current?.id?"selected":""}>${esc(e.name)}</option>`).join("")}</select><button class="btn btn-sm" id="env-new">＋ New</button></div>`:""}<div id="env-editor">${renderVariables(current)}</div>`,[{label:"Cancel",action:closeModal},{label:"Save environment",primary:true,action:async()=>{try{const id=document.querySelector<HTMLInputElement>("#env-id")?.value||"";const name=document.querySelector<HTMLInputElement>("#env-name")?.value||"Environment";const variables=[...document.querySelectorAll<HTMLElement>("[data-env-row]")].map(row=>({id:"",enabled:row.querySelector<HTMLInputElement>('[data-v="enabled"]')!.checked,key:row.querySelector<HTMLInputElement>('[data-v="key"]')!.value,initialValue:row.querySelector<HTMLInputElement>('[data-v="initialValue"]')!.value,currentValue:row.querySelector<HTMLInputElement>('[data-v="currentValue"]')!.value,secret:row.querySelector<HTMLInputElement>('[data-v="secret"]')!.checked})).filter(v=>v.key);const saved=await api("SaveEnvironment",{id,workspaceId:activeWorkspace(),name,variables});const index=state.environments.findIndex((e:AnyRecord)=>e.id===saved.id);if(index>=0)state.environments[index]=saved;else state.environments.push(saved);state.settings.activeEnvironmentId=saved.id;await api("SaveSettings",state.settings);closeModal();renderShell();toast("Environment saved") }catch(e){toast(String(e),true)}}}],true);document.querySelector("#env-new")?.addEventListener("click",()=>{const editor=document.querySelector("#env-editor");if(editor)editor.innerHTML=renderVariables(null)});document.querySelector("#env-modal-select")?.addEventListener("change",e=>{const selected=envs.find((x:AnyRecord)=>x.id===(e.target as HTMLSelectElement).value);const editor=document.querySelector("#env-editor");if(editor)editor.innerHTML=renderVariables(selected)})}

function showSettings(){const s=state.settings;showModal("Settings",`<div class="field-grid"><div class="field"><label>Theme</label><select class="select" id="set-theme"><option value="dark" ${s.theme==="dark"?"selected":""}>Dark</option><option value="light" ${s.theme==="light"?"selected":""}>Light</option><option value="system" ${s.theme==="system"?"selected":""}>System</option></select></div><div class="field"><label>Log level</label><select class="select" id="set-log"><option>INFO</option><option ${s.logLevel==="DEBUG"?"selected":""}>DEBUG</option><option ${s.logLevel==="WARN"?"selected":""}>WARN</option><option ${s.logLevel==="ERROR"?"selected":""}>ERROR</option></select></div><div class="field"><label>History retention (days)</label><input class="input" type="number" id="set-retention" value="${s.historyRetentionDays}"></div><div class="field"><label>Maximum preview (MB)</label><input class="input" type="number" id="set-preview" value="${Math.round(s.maxResponsePreviewSize/1048576)}"></div><div class="field wide"><label><input type="checkbox" id="set-history-bodies" ${s.storeHistoryBodies?"checked":""}> Store request and response bodies in history</label></div><div class="field wide"><label>About</label><div class="about-box"><div><strong>Metriyon API ${esc(state.version)}</strong><br><span class="muted">${esc(state.goVersion)} · commit ${esc(state.commit)} · built ${esc(state.buildDate)}</span></div><button class="btn btn-sm" data-action="check-updates">Check for updates</button></div></div></div>`,[{label:"Cancel",action:closeModal},{label:"Save settings",primary:true,action:async()=>{s.theme=document.querySelector<HTMLSelectElement>("#set-theme")!.value;s.logLevel=document.querySelector<HTMLSelectElement>("#set-log")!.value;s.historyRetentionDays=Number(document.querySelector<HTMLInputElement>("#set-retention")!.value)||30;s.maxResponsePreviewSize=(Number(document.querySelector<HTMLInputElement>("#set-preview")!.value)||10)*1048576;s.storeHistoryBodies=document.querySelector<HTMLInputElement>("#set-history-bodies")!.checked;await api("SaveSettings",s);closeModal();applyTheme();renderShell();toast("Settings saved")}}])}

async function checkForUpdates(force=false){
  if(updateCheckInProgress)return;
  updateCheckInProgress=true;
  try{
    const info=await api("CheckForUpdates",force);
    if(!info?.checked)return;
    if(info.updateAvailable){showUpdateAvailable(info);return}
    if(force)toast(`You already have the latest version (v${info.currentVersion}).`)
  }catch(error){
    if(force)toast(`Could not check for updates: ${error}`,true)
  }finally{updateCheckInProgress=false}
}

function showUpdateAvailable(info:AnyRecord){
  const notes=String(info.notes||"").trim();
  const published=info.publishedAt?new Date(info.publishedAt).toLocaleDateString():"";
  showModal("Há uma nova versão disponível!",`<div class="update-card"><div class="update-versions"><div><small>Versão instalada</small><strong>v${esc(info.currentVersion)}</strong></div><span>→</span><div><small>Nova versão</small><strong>v${esc(info.latestVersion)}</strong></div></div>${published?`<p class="muted">Publicada em ${esc(published)}</p>`:""}${notes?`<div class="update-notes"><strong>Novidades</strong><div>${esc(notes).replace(/\n/g,"<br>")}</div></div>`:""}<p class="muted update-security">O download será aberto na Release oficial do MetriyonAPI no GitHub.</p></div>`,[{label:"Lembrar depois",action:closeModal},{label:"Baixar atualização",primary:true,action:async()=>{try{await api("OpenExternalURL",info.releaseUrl);closeModal()}catch(error){toast(String(error),true)}}}],true)
}

function showSearch(){const rows=requestsForWorkspace();showModal("Global search",`<input class="input" id="search-input" style="width:100%" placeholder="Search requests, URLs and descriptions" autofocus><div id="search-results" style="margin-top:10px">${rows.map(renderSearchResult).join("")}</div>`,[{label:"Close",action:closeModal}],true);document.querySelector<HTMLInputElement>("#search-input")?.addEventListener("input",e=>{const q=(e.target as HTMLInputElement).value.toLowerCase();const matches=rows.filter((r:AnyRecord)=>`${r.name} ${r.url} ${r.description}`.toLowerCase().includes(q));document.querySelector("#search-results")!.innerHTML=matches.map(renderSearchResult).join("")})}
function renderSearchResult(r:AnyRecord){return `<div class="tree-row" data-search-open="${r.id}"><span class="method ${methodClass(r)}">${methodClass(r)}</span><span class="label"><strong>${esc(r.name)}</strong><br><small class="muted">${esc(r.url)}</small></span></div>`}

