function refreshFlowEdges(flow:AnyRecord){const svg=document.querySelector<SVGSVGElement>("#flow-connections");if(svg)svg.innerHTML=`${renderFlowEdges(flow)}<path id="flow-preview-edge" class="flow-edge preview" d="" hidden></path>`}

document.addEventListener("contextmenu",event=>{const source=event.target as HTMLElement;const tab=source.closest<HTMLElement>("[data-tab]");if(tab){event.preventDefault();showTabMenu(tab.dataset.tab!,event.clientX,event.clientY);return}const target=source.closest<HTMLElement>("[data-tree-kind]");if(!target)return;event.preventDefault();showTreeMenu(target.dataset.treeKind!,target.dataset.treeId!,event.clientX,event.clientY)});
document.addEventListener("dragstart",event=>{if((event.target as HTMLElement).closest("button")){event.preventDefault();return}const requestRow=(event.target as HTMLElement).closest<HTMLElement>("[data-open-request][draggable=true]");const folderRow=(event.target as HTMLElement).closest<HTMLElement>("[data-folder-drag][draggable=true]");if(!event.dataTransfer||(!requestRow&&!folderRow))return;event.dataTransfer.effectAllowed="move";if(requestRow)event.dataTransfer.setData("application/x-forge-request",requestRow.dataset.openRequest!);if(folderRow)event.dataTransfer.setData("application/x-forge-folder",folderRow.dataset.folderDrag!);(requestRow||folderRow)!.classList.add("dragging");closeContextMenu()});
document.addEventListener("dragend",event=>{(event.target as HTMLElement).closest(".tree-row")?.classList.remove("dragging");document.querySelectorAll(".drop-target").forEach(item=>item.classList.remove("drop-target"))});
document.addEventListener("dragover",event=>{const target=(event.target as HTMLElement).closest<HTMLElement>("[data-drop-collection]");const types=event.dataTransfer?.types||[];if(!target||(!types.includes("application/x-forge-request")&&!types.includes("application/x-forge-folder")))return;event.preventDefault();event.dataTransfer!.dropEffect="move";document.querySelectorAll(".drop-target").forEach(item=>{if(item!==target)item.classList.remove("drop-target")});target.classList.add("drop-target")});
document.addEventListener("dragleave",event=>{const target=(event.target as HTMLElement).closest<HTMLElement>("[data-drop-collection]");if(target&&!target.contains(event.relatedTarget as Node))target.classList.remove("drop-target")});
document.addEventListener("drop",event=>{const target=(event.target as HTMLElement).closest<HTMLElement>("[data-drop-collection]");if(!target||!event.dataTransfer)return;event.preventDefault();target.classList.remove("drop-target");const requestId=event.dataTransfer.getData("application/x-forge-request");const folderId=event.dataTransfer.getData("application/x-forge-folder");if(requestId)void moveRequest(requestId,target.dataset.dropCollection!,target.dataset.dropFolder||"");else if(folderId)void moveFolder(folderId,target.dataset.dropCollection!,target.dataset.dropFolder||"")});
document.addEventListener("scroll",closeContextMenu,true);

document.addEventListener("keydown",event=>{const command=event.ctrlKey||event.metaKey;const target=event.target as HTMLElement;if(event.key==="Enter"&&!command&&target.matches(".flow-name")){event.preventDefault();(target as HTMLInputElement).blur();void persistFlow();return}if(event.key==="Enter"&&!command&&target.matches(".request-name")){event.preventDefault();(target as HTMLInputElement).blur();void saveCurrent();return}if(event.key==="Enter"&&!command&&(target.id==="rename-value"||target.id==="flow-new-name")){event.preventDefault();document.querySelector<HTMLButtonElement>("#modal-buttons .btn-primary")?.click();return}if(command&&event.key==="Enter"){event.preventDefault();if(activeFlowId)void runFlow();else void sendCurrent()}if(command&&event.key.toLowerCase()==="s"){event.preventDefault();if(activeFlowId)void persistFlow();else void saveCurrent()}if(command&&event.key.toLowerCase()==="n"){event.preventDefault();void createRequest("REST")}if(command&&event.key.toLowerCase()==="w"){event.preventDefault();if(activeFlowId){activeFlowId="";selectedFlowNodeId="";renderTabs();renderSidebar();renderWorkspace()}else if(activeId)void closeTab(activeId)}if(command&&event.key.toLowerCase()==="k"){event.preventDefault();showSearch()}if(command&&event.key.toLowerCase()==="l"){event.preventDefault();document.querySelector<HTMLInputElement>("#url-input")?.focus()}if(command&&event.shiftKey&&event.key.toLowerCase()==="f"){event.preventDefault();document.querySelector<HTMLElement>('[data-action="format-body"]')?.click()}if(event.key==="Escape"){flowConnectionDrag=null;closeModal()}});

void bootstrap();
